const __aivicBundle_7_detectRestrictionChanges = (() => {
  function detectRestrictionChanges(input: {
    restriction: {
      user_id: string;
      restriction_name: string;
      previous_update_at: Date;
      current_update_at: null | Date;
    };
    current_time: Date;
    threshold_days: number;
  }): {
    is_change_detected: boolean;
    days_since_last_update: number;
    priority_judgment_triggered: boolean;
    requires_update: boolean;
  } {
    const { restriction, current_time, threshold_days } = input;
  
    const timeDiffMs =
      current_time.getTime() - restriction.previous_update_at.getTime();
    const days_since_last_update = timeDiffMs / (1000 * 60 * 60 * 24);
  
    const is_change_detected = days_since_last_update >= threshold_days;
    const priority_judgment_triggered = is_change_detected;
    const requires_update = is_change_detected;
  
    return {
      is_change_detected,
      days_since_last_update,
      priority_judgment_triggered,
      requires_update,
    };
  }
  return { detectRestrictionChanges };
})();
