/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMenuConstraintFulfillmentScore exports=calculateMenuConstraintFulfillmentScore */
const __aivicBundle_11_calculateMenuConstraintFulfillmentScore = (() => {
  function calculateMenuConstraintFulfillmentScore(menu_input: {
    menu_id: string;
    dishes: Array<{
      dish_id: string;
      dish_name: string;
      nutrition: {
        calories: number;
        protein_g: number;
        carbs_g: number;
        fat_g: number;
      };
      allergens: string[];
      cost_yen: number;
      cooking_time_minutes: number;
    }>;
    constraints: {
      nutrition: {
        target_calories: number;
        tolerance_calories_percent: number;
        target_protein_g: number;
        tolerance_protein_percent: number;
      };
      allergens_exclude: string[];
      budget_max_yen: number;
      cooking_time_max_minutes: number;
    };
  }): ConstraintFulfillmentScore {
    if (!String(menu_input.menu_id).trim()) {
      throw new Error("menu_id is required");
    }
  
    const dishes = menu_input.dishes;
    const constraints = menu_input.constraints;
  
    const totalCalories = dishes.reduce((sum, dish) => sum + dish.nutrition.calories, 0);
    const totalProtein = dishes.reduce((sum, dish) => sum + dish.nutrition.protein_g, 0);
    const totalCost = dishes.reduce((sum, dish) => sum + dish.cost_yen, 0);
    const totalCookingTime = dishes.reduce((sum, dish) => sum + dish.cooking_time_minutes, 0);
  
    const detectedAllergens: string[] = [];
    dishes.forEach((dish) => {
      dish.allergens.forEach((allergen) => {
        if (!detectedAllergens.includes(allergen)) {
          detectedAllergens.push(allergen);
        }
      });
    });
  
    const calorieTarget = constraints.nutrition.target_calories;
    const calorieTolerancePercent = constraints.nutrition.tolerance_calories_percent;
    const calorieMin = calorieTarget * (1 - calorieTolerancePercent / 100);
    const calorieMax = calorieTarget * (1 + calorieTolerancePercent / 100);
  
    let caloriesAchievementPercent = 100;
    if (totalCalories < calorieMin) {
      caloriesAchievementPercent = (totalCalories / calorieTarget) * 100;
    } else if (totalCalories > calorieMax) {
      caloriesAchievementPercent = (calorieMax / totalCalories) * 100;
    }
  
    const proteinTarget = constraints.nutrition.target_protein_g;
    const proteinTolerancePercent = constraints.nutrition.tolerance_protein_percent;
    const proteinMin = proteinTarget * (1 - proteinTolerancePercent / 100);
    const proteinMax = proteinTarget * (1 + proteinTolerancePercent / 100);
  
    let proteinAchievementPercent = 100;
    let proteinStatus = "achieved";
    if (totalProtein < proteinMin) {
      proteinAchievementPercent = (totalProtein / proteinTarget) * 100;
      proteinStatus = "insufficient";
    } else if (totalProtein > proteinMax) {
      proteinAchievementPercent = (totalProtein / proteinMax) * 100;
      proteinStatus = "exceeded";
    }
  
    const nutritionScore = Math.round(
      (caloriesAchievementPercent + proteinAchievementPercent) / 2
    );
  
    const isAllergenCompliant = !detectedAllergens.some((allergen) =>
      constraints.allergens_exclude.includes(allergen)
    );
    const allergenScore = isAllergenCompliant ? 100 : 0;
  
    const budgetMax = constraints.budget_max_yen;
    const budgetAchievementPercent = (totalCost / budgetMax) * 100;
    const budgetScore = Math.min(100, Math.round(budgetAchievementPercent));
    const isWithinBudget = totalCost <= budgetMax;
  
    const cookingTimeMax = constraints.cooking_time_max_minutes;
    const timeAchievementPercent = (cookingTimeMax / totalCookingTime) * 100;
    const cookingTimeScore = Math.min(100, Math.round(timeAchievementPercent * 10) / 10);
    const isWithinTimeLimit = totalCookingTime <= cookingTimeMax;
    const excessMinutes = Math.max(0, totalCookingTime - cookingTimeMax);
  
    const overallScore = (nutritionScore + allergenScore + budgetScore + cookingTimeScore) / 4;
  
    const nutritionDetail = {
      actual_calories: totalCalories,
      target_calories: calorieTarget,
      calories_achievement_percent: caloriesAchievementPercent,
      actual_protein_g: totalProtein,
      target_protein_g: proteinTarget,
      protein_achievement_percent: Math.round(proteinAchievementPercent * 100) / 100,
      protein_status: proteinStatus,
    };
  
    const allergenDetail = {
      excluded_allergens: constraints.allergens_exclude,
      detected_allergens: detectedAllergens,
      is_compliant: isAllergenCompliant,
    };
  
    const budgetDetail = {
      actual_cost_yen: totalCost,
      budget_max_yen: budgetMax,
      budget_achievement_percent: Math.round(budgetAchievementPercent * 100) / 100,
      is_within_budget: isWithinBudget,
    };
  
    const cookingTimeDetail = {
      actual_cooking_time_minutes: totalCookingTime,
      max_cooking_time_minutes: cookingTimeMax,
      time_achievement_percent: Math.round(timeAchievementPercent * 10) / 10,
      is_within_limit: isWithinTimeLimit,
      excess_minutes: excessMinutes,
    };
  
    return {
      nutrition_score: nutritionScore,
      allergen_score: allergenScore,
      budget_score: budgetScore,
      cooking_time_score: cookingTimeScore,
      overall_score: overallScore,
      nutrition_detail: nutritionDetail,
      allergen_detail: allergenDetail,
      budget_detail: budgetDetail,
      cooking_time_detail: cookingTimeDetail,
    };
  }
  return { calculateMenuConstraintFulfillmentScore };
})();
export const calculateMenuConstraintFulfillmentScore = __aivicBundle_11_calculateMenuConstraintFulfillmentScore.calculateMenuConstraintFulfillmentScore;
