/* AIVIC_FUNCTION_BUNDLE_START owner=calculateMenuConstraintScores exports=calculateMenuConstraintScores */
const __aivicBundle_12_calculateMenuConstraintScores = (() => {
  function calculateMenuConstraintScores(input: {
    nutritionScore: number;
    allergyScore: number;
    ingredientAvailabilityScore: number;
    cookingDifficultyScore: number;
    costScore: number;
  }): MenuConstraintScores {
    const weights = {
      nutrition: 0.25,
      allergy: 0.25,
      ingredientAvailability: 0.2,
      cookingDifficulty: 0.15,
      cost: 0.15,
    };
  
    const overallScore =
      input.nutritionScore * weights.nutrition +
      input.allergyScore * weights.allergy +
      input.ingredientAvailabilityScore * weights.ingredientAvailability +
      input.cookingDifficultyScore * weights.cookingDifficulty +
      input.costScore * weights.cost;
  
    return {
      nutritionScore: input.nutritionScore,
      allergyScore: input.allergyScore,
      ingredientAvailabilityScore: input.ingredientAvailabilityScore,
      cookingDifficultyScore: input.cookingDifficultyScore,
      costScore: input.costScore,
      overallScore,
    };
  }
  return { calculateMenuConstraintScores };
})();
export const calculateMenuConstraintScores = __aivicBundle_12_calculateMenuConstraintScores.calculateMenuConstraintScores;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateMenuConstraintScores */

