/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeHighRatedDishesForMealGeneration exports=prioritizeHighRatedDishesForMealGeneration */
const __aivicBundle_26_prioritizeHighRatedDishesForMealGeneration = (() => {
  function prioritizeHighRatedDishesForMealGeneration(input: {
    userId: string;
    familyMemberId: string;
    evaluatedDishes: Array<{
      dishId: string;
      dishName: string;
      averageRating: number;
      requestCount: number;
      ingredients: Array<{
        ingredientId: string;
        name: string;
        status: string;
      }>;
    }>;
    mealGenerationDate: Date;
    priorityThreshold: number;
  }): {
    success: boolean;
    error?: string;
    reflectedToMealGeneration: boolean;
    prioritizedDishList?: string[];
  } {
    // Validate required inputs
    if (!String(input.userId).trim()) {
      throw new Error("userId is required");
    }
    if (!String(input.familyMemberId).trim()) {
      throw new Error("familyMemberId is required");
    }
    if (!input.mealGenerationDate) {
      throw new Error("mealGenerationDate is required");
    }
  
    const {
      evaluatedDishes,
      priorityThreshold,
    } = input;
  
    // High-rated dishes filter (rating >= priorityThreshold)
    const highRatedDishes = evaluatedDishes.filter(
      (dish) => dish.averageRating >= priorityThreshold
    );
  
    // No high-rated dishes found
    if (highRatedDishes.length === 0) {
      return {
        success: false,
        error: "優先度閾値以上の高評価料理が見つかりません",
        reflectedToMealGeneration: false,
      };
    }
  
    // Filter dishes that have at least one available (non-discontinued) ingredient
    const availableDishes = highRatedDishes.filter((dish) => {
      const hasAvailableIngredient = dish.ingredients.some(
        (ingredient) => ingredient.status !== "discontinued"
      );
      return hasAvailableIngredient;
    });
  
    // All high-rated dishes contain only discontinued ingredients
    if (availableDishes.length === 0) {
      return {
        success: false,
        error: "廃盤食材のみで構成されています",
        reflectedToMealGeneration: false,
      };
    }
  
    // Sort by priority score (averageRating * requestCount) in descending order
    const prioritizedDishList = availableDishes
      .sort((a, b) => {
        const scoreA = a.averageRating * a.requestCount;
        const scoreB = b.averageRating * b.requestCount;
        return scoreB - scoreA;
      })
      .map((dish) => dish.dishId);
  
    return {
      success: true,
      reflectedToMealGeneration: true,
      prioritizedDishList,
    };
  }
  return { prioritizeHighRatedDishesForMealGeneration };
})();
export const prioritizeHighRatedDishesForMealGeneration = __aivicBundle_26_prioritizeHighRatedDishesForMealGeneration.prioritizeHighRatedDishesForMealGeneration;
/* AIVIC_FUNCTION_BUNDLE_END owner=prioritizeHighRatedDishesForMealGeneration */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementDashboard exports=calculateNutritionAchievementDashboard */
const __aivicBundle_27_calculateNutritionAchievementDashboard = (() => {
  function calculateNutritionAchievementDashboard(input: any): any {
    const nutritionItems = input.nutritionItems || [];
  
    const achievementScores: Record<string, number> = {};
    const improvementGaps: Record<string, number> = {};
    const gapArray: Array<{ itemId: string; itemName: string; gap: number; actualValue: number; targetValue: number }> = [];
  
    // Calculate achievement scores and gaps for each nutrition item
    for (const item of nutritionItems) {
      const achievement = (item.actualValue / item.targetValue) * 100;
      const gap = item.targetValue - item.actualValue;
  
      achievementScores[item.itemId] = Math.round(achievement * 10) / 10;
      improvementGaps[item.itemId] = gap;
  
      gapArray.push({
        itemId: item.itemId,
        itemName: item.itemName,
        gap: gap,
        actualValue: item.actualValue,
        targetValue: item.targetValue,
      });
    }
  
    // Sort gaps in descending order for priority ranking
    const gapSorted = [...gapArray].sort((a, b) => b.gap - a.gap);
  
    const gapPriorities = gapSorted
      .filter((item) => item.gap > 0)
      .map((item, index) => ({
        itemId: item.itemId,
        itemName: item.itemName,
        gap: item.gap,
        priority: index + 1,
      }));
  
    // Classify items into above and below 100% achievement
    const above100Percent: Array<{ itemId: string; itemName: string; achievement: number }> = [];
    const below100Percent: Array<{ itemId: string; itemName: string; achievement: number }> = [];
  
    for (const item of nutritionItems) {
      const achievement = Math.round((item.actualValue / item.targetValue) * 100 * 10) / 10;
      if (achievement >= 100) {
        above100Percent.push({
          itemId: item.itemId,
          itemName: item.itemName,
          achievement: achievement,
        });
      } else {
        below100Percent.push({
          itemId: item.itemId,
          itemName: item.itemName,
          achievement: achievement,
        });
      }
    }
  
    // Create visualization sorted by gap descending
    const sortedByGapDescending: Array<{
      rank: number;
      itemId: string;
      itemName: string;
      achievement: number;
      gap: number;
      color: string;
    }> = [];
  
    for (let i = 0; i < gapSorted.length; i++) {
      const itemData = gapSorted[i];
      const achievement = Math.round((itemData.actualValue / itemData.targetValue) * 100 * 10) / 10;
  
      let color = "lightyellow";
      if (achievement < 50) {
        color = "red";
      } else if (achievement < 70) {
        color = "orange";
      } else if (achievement < 90) {
        color = "yellow";
      }
  
      sortedByGapDescending.push({
        rank: i + 1,
        itemId: itemData.itemId,
        itemName: itemData.itemName,
        achievement: achievement,
        gap: itemData.gap,
        color: color,
      });
    }
  
    const result: any = {
      achievementScores,
      improvementGaps,
      gapPriorities,
      classification: {
        above100Percent,
        below100Percent,
      },
      visualization: {
        format: "ranking",
        sortedByGapDescending,
      },
    };
  
    // If userId or evaluationDate is provided, add additional analysis fields
    if (input.userId !== undefined || input.evaluationDate !== undefined) {
      const improvementTargets = gapArray
        .filter((item) => item.gap > 0)
        .sort((a, b) => b.gap - a.gap)
        .map((item) => {
          return {
            nutrientId: item.itemId,
            nutrientName: item.itemName,
            achievementGap: item.gap,
            achievementRate: Math.round((item.actualValue / item.targetValue) * 100 * 10) / 10,
          };
        });
  
      const totalItems = nutritionItems.length;
      const achievedItems = nutritionItems.filter(
        (item: any) => (item.actualValue / item.targetValue) * 100 >= 100
      ).length;
      const improvementNeededItems = totalItems - achievedItems;
  
      const overallAchievementRate =
        nutritionItems.reduce((sum: number, item: any) => {
          return sum + (item.actualValue / item.targetValue) * 100;
        }, 0) / totalItems;
  
      result.improvementTargets = improvementTargets;
      result.totalItems = totalItems;
      result.achievedItems = achievedItems;
      result.improvementNeededItems = improvementNeededItems;
      result.overallAchievementRate = Math.round(overallAchievementRate * 100) / 100;
    }
  
    return result;
  }
  return { calculateNutritionAchievementDashboard };
})();
export const calculateNutritionAchievementDashboard = __aivicBundle_27_calculateNutritionAchievementDashboard.calculateNutritionAchievementDashboard;
