const __aivicBundle_28_calculateNutritionAchievementAndGaps = (() => {
  function calculateNutritionAchievementAndGaps(
    userId: string,
    nutritionItems: Array<{
      nutrition_id: string;
      nutrition_name: string;
      unit: string;
      target_value: number;
      actual_value: number;
    }>,
    analysisDate: string,
    logCallback: (log: string) => void
  ): {
    status: 'success' | 'success_with_warnings';
    achievement_scores: Array<{
      nutrition_id: string;
      nutrition_name: string;
      achievement_percentage: number | null;
      display_status: string;
    }>;
    improvement_gaps: Array<{
      nutrition_id: string;
      nutrition_name: string;
      gap_value: number;
      priority_rank: number;
    }>;
    dashboard_display: Array<{
      nutrition_id: string;
      label: string;
      value_display: string;
      is_calculable: boolean;
      achievement_rate?: number;
    }>;
    error_count: number;
    processed_date: string;
  } {
    if (!userId || !userId.trim()) {
      throw new Error('userId is required and must not be empty');
    }
  
    let errorCount = 0;
    const achievementScores: Array<{
      nutrition_id: string;
      nutrition_name: string;
      achievement_percentage: number | null;
      display_status: string;
    }> = [];
    const improvementGaps: Array<{
      nutrition_id: string;
      nutrition_name: string;
      gap_value: number;
      priority_rank: number;
    }> = [];
    const dashboardDisplay: Array<{
      nutrition_id: string;
      label: string;
      value_display: string;
      is_calculable: boolean;
      achievement_rate?: number;
    }> = [];
  
    for (const item of nutritionItems) {
      if (item.target_value === 0) {
        errorCount++;
        logCallback(
          `警告: 栄養項目 "${item.nutrition_name}" (${item.nutrition_id}) の目標値がゼロです。ゼロ除算を回避するため計算をスキップします。`
        );
  
        achievementScores.push({
          nutrition_id: item.nutrition_id,
          nutrition_name: item.nutrition_name,
          achievement_percentage: null,
          display_status: '計算不可',
        });
  
        dashboardDisplay.push({
          nutrition_id: item.nutrition_id,
          label: item.nutrition_name,
          value_display: '計算不可',
          is_calculable: false,
        });
      } else {
        const achievementPercentage = Math.round(
          (item.actual_value / item.target_value) * 100
        );
        const displayStatus = '達成';
  
        achievementScores.push({
          nutrition_id: item.nutrition_id,
          nutrition_name: item.nutrition_name,
          achievement_percentage: achievementPercentage,
          display_status: displayStatus,
        });
  
        dashboardDisplay.push({
          nutrition_id: item.nutrition_id,
          label: item.nutrition_name,
          value_display: `${achievementPercentage}%`,
          is_calculable: true,
          achievement_rate: achievementPercentage,
        });
  
        if (item.actual_value < item.target_value) {
          const gapValue = item.target_value - item.actual_value;
          improvementGaps.push({
            nutrition_id: item.nutrition_id,
            nutrition_name: item.nutrition_name,
            gap_value: gapValue,
            priority_rank: 0,
          });
        }
      }
    }
  
    improvementGaps.sort((a, b) => b.gap_value - a.gap_value);
    improvementGaps.forEach((gap, index) => {
      gap.priority_rank = index + 1;
    });
  
    const status: 'success' | 'success_with_warnings' =
      errorCount > 0 ? 'success_with_warnings' : 'success';
  
    return {
      status,
      achievement_scores: achievementScores,
      improvement_gaps: improvementGaps,
      dashboard_display: dashboardDisplay,
      error_count: errorCount,
      processed_date: analysisDate,
    };
  }
  return { calculateNutritionAchievementAndGaps };
})();
export const calculateNutritionAchievementAndGaps = __aivicBundle_28_calculateNutritionAchievementAndGaps.calculateNutritionAchievementAndGaps;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutritionAchievementAndGaps */

