const __aivicBundle_42_calculateMealPlanScores = (() => {
  function calculateMealPlanScores(
    mealPlans: Array<{
      id?: string;
      name?: string;
      dishes: string[];
      ingredients?: Array<{ name: string; quantity: number; unit: string }>;
      nutritionBalance?: number;
    }>,
    distributorData: Record<
      string,
      {
        inStock: boolean;
        stockLevel: number;
        price: number;
        seasonalDiscount: number;
      }
    >
  ): MealPlanScore[] {
    return mealPlans.map((plan) => {
      const ingredients = plan.ingredients || [];
  
      // Calculate stock fulfillment score (0-100)
      let stockFulfillmentScore = 0;
      if (ingredients.length > 0) {
        const stockLevels = ingredients
          .map((ing) => {
            const distributorInfo = distributorData[ing.name];
            return distributorInfo ? distributorInfo.stockLevel : 0;
          })
          .filter((level) => level > 0);
  
        stockFulfillmentScore =
          stockLevels.length > 0
            ? stockLevels.reduce((a, b) => a + b, 0) / stockLevels.length
            : 0;
      }
  
      // Calculate price score (0-100)
      let priceScore = 0;
      if (ingredients.length > 0) {
        const priceData = ingredients
          .map((ing) => {
            const distributorInfo = distributorData[ing.name];
            if (!distributorInfo) return null;
            return {
              price: distributorInfo.price,
              discount: distributorInfo.seasonalDiscount,
            };
          })
          .filter((data) => data !== null);
  
        if (priceData.length > 0) {
          const avgDiscount =
            priceData.reduce((sum, data) => sum + data.discount, 0) /
            priceData.length;
          priceScore = 100 - avgDiscount * 0.5;
        }
      }
  
      // Nutrition balance score (0-100)
      const nutritionBalanceScore = plan.nutritionBalance || 0;
  
      // Total score calculation: (stock × 0.3) + (price × 0.3) + (nutrition × 0.4)
      const totalScore =
        stockFulfillmentScore * 0.3 +
        priceScore * 0.3 +
        nutritionBalanceScore * 0.4;
  
      return {
        mealPlanId: plan.id || "",
        satisfactionScore: 0,
        nutritionScore: nutritionBalanceScore,
        budgetScore: priceScore,
        cookingTimeScore: 0,
        inventoryScore: stockFulfillmentScore,
        totalScore,
        recommendedAction: totalScore >= 85 ? "adopt" : totalScore >= 70 ? "modify" : "reject",
        stockFulfillmentScore,
        priceScore,
        nutritionBalanceScore,
      };
    });
  }
  return { calculateMealPlanScores };
})();
