/* AIVIC_FUNCTION_BUNDLE_START owner=calculatePredictionAccuracy exports=calculatePredictionAccuracy */
const __aivicBundle_50_calculatePredictionAccuracy = (() => {
  function calculatePredictionAccuracy(
    forecastedValues: number[],
    actualValues: number[]
  ): PredictionAccuracyMetrics {
    if (
      !Array.isArray(forecastedValues) ||
      !Array.isArray(actualValues) ||
      forecastedValues.length === 0 ||
      actualValues.length === 0 ||
      forecastedValues.length !== actualValues.length
    ) {
      return {
        overallAccuracy: 0,
        categoryAccuracy: {},
        rmse: 0,
        mae: 0,
        mape: 0,
        accuracyRate: 0,
      };
    }
  
    const n = forecastedValues.length;
    let sumSquaredError = 0;
    let sumAbsoluteError = 0;
    let sumAbsolutePercentageError = 0;
  
    for (let i = 0; i < n; i++) {
      const forecast = forecastedValues[i];
      const actual = actualValues[i];
      const error = forecast - actual;
      const absError = Math.abs(error);
  
      sumSquaredError += error * error;
      sumAbsoluteError += absError;
  
      if (actual !== 0) {
        const percentageError = Math.abs((forecast - actual) / actual) * 100;
        sumAbsolutePercentageError += percentageError;
      }
    }
  
    const rmse = Math.sqrt(sumSquaredError / n);
    const mae = sumAbsoluteError / n;
    const mape = sumAbsolutePercentageError / n;
  
    const accuracyRate = Math.max(0, Math.min(100, 100 - mape)) / 100;
    const overallAccuracy = accuracyRate;
  
    return {
      overallAccuracy,
      categoryAccuracy: {},
      rmse: Math.round(rmse * 100) / 100,
      mae: Math.round(mae * 100) / 100,
      mape: Math.round(mape * 100) / 100,
      accuracyRate,
    };
  }
  return { calculatePredictionAccuracy };
})();
