/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeNutritionGapAndGenerateProposal exports=analyzeNutritionGapAndGenerateProposal */
const __aivicBundle_52_analyzeNutritionGapAndGenerateProposal = (() => {
  function analyzeNutritionGapAndGenerateProposal(input: {
    userId: string;
    measurementDate: string;
    nutritionMetrics: Array<{
      nutrientId: string;
      targetValue: number;
      actualValue: number | null;
      unit?: string;
    }>;
    mealRecordCount?: number;
    recordingTimestamp?: string;
  }): {
    totalAchievementScore: number;
    achievementScores: Record<string, number>;
    improvementGaps: Record<string, number>;
    prioritizedImprovementItems: Array<{
      nutrientId: string;
      gap: number;
      achievementScore: number;
      priority: number;
    }>;
    status: string;
    proposalGenerated: boolean;
  } {
    // Validation: userId
    if (!input.userId || input.userId.trim() === "") {
      throw new Error("ユーザーID が必須です");
    }
  
    // Validation: measurementDate
    const dateRegex = /^\d{4}-\d{2}-\d{2}$/;
    if (!dateRegex.test(input.measurementDate)) {
      throw new Error("測定日付 のフォーマットが無効です");
    }
  
    // Validation: nutritionMetrics not empty
    if (!input.nutritionMetrics || input.nutritionMetrics.length === 0) {
      throw new Error("栄養項目 が必須です");
    }
  
    // Detect missing data
    const missingNutrientIds: string[] = [];
    for (const metric of input.nutritionMetrics) {
      if (metric.actualValue === null || metric.actualValue === undefined) {
        missingNutrientIds.push(metric.nutrientId);
      }
    }
  
    if (missingNutrientIds.length > 0) {
      const missingList = missingNutrientIds.join(", ");
      const count = missingNutrientIds.length;
      throw new Error(
        `実績データ欠損: ${count}件の欠損データを検出しました (${missingList})`
      );
    }
  
    // Calculate achievement scores and gaps
    const achievementScores: Record<string, number> = {};
    const improvementGaps: Record<string, number> = {};
    const priorityItems: Array<{
      nutrientId: string;
      gap: number;
      achievementScore: number;
      priority: number;
    }> = [];
  
    for (const metric of input.nutritionMetrics) {
      const actualValue = metric.actualValue as number;
      const targetValue = metric.targetValue;
  
      // Achievement score: (actual / target) * 100
      const achievementScore = (actualValue / targetValue) * 100;
      achievementScores[metric.nutrientId] = Math.round(achievementScore);
  
      // Gap: target - actual
      const gap = targetValue - actualValue;
      improvementGaps[metric.nutrientId] = gap;
  
      // Store for prioritization
      priorityItems.push({
        nutrientId: metric.nutrientId,
        gap: gap,
        achievementScore: Math.round(achievementScore),
        priority: 0 // Will be assigned after sorting
      });
    }
  
    // Calculate total achievement score
    const totalAchievementScore =
      Object.values(achievementScores).reduce((sum, score) => sum + score, 0) /
      Object.keys(achievementScores).length;
  
    // Determine status and proposal generation
    const allAchieved = Object.values(achievementScores).every(
      (score) => score >= 100
    );
    const status = allAchieved ? "target_achieved" : "success";
    const proposalGenerated = !allAchieved;
  
    // Sort by gap (descending) and assign priority
    priorityItems.sort((a, b) => b.gap - a.gap);
    priorityItems.forEach((item, index) => {
      item.priority = index + 1;
    });
  
    return {
      totalAchievementScore: Math.round(totalAchievementScore),
      achievementScores,
      improvementGaps,
      prioritizedImprovementItems: priorityItems,
      status,
      proposalGenerated
    };
  }
  return { analyzeNutritionGapAndGenerateProposal };
})();
export const analyzeNutritionGapAndGenerateProposal: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_52_analyzeNutritionGapAndGenerateProposal.analyzeNutritionGapAndGenerateProposal as (...args: any[]) => any)(...args);
