/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCorrelationCoefficients exports=calculateCorrelationCoefficients */
const __aivicBundle_53_calculateCorrelationCoefficients = (() => {
  function calculateCorrelationCoefficients(input: {
    weatherData?: { temperature?: number[]; precipitation?: number[] };
    eventData?: { isWeekend?: number[]; isSale?: number[] };
    competitorData?: { discountRate?: number[]; campaignIntensity?: number[] };
    actualDemand?: number[];
  }): {
    weatherCorrelation: { temperature: number; precipitation: number };
    eventCorrelation: { isWeekend: number; isSale: number };
    competitorCorrelation: { discountRate: number; campaignIntensity: number };
    timestamp: string;
  } {
    const computePearsonCorrelation = (x: number[], y: number[]): number => {
      if (x.length === 0 || y.length === 0 || x.length !== y.length) {
        return 0;
      }
  
      const n = x.length;
      const meanX = x.reduce((a, b) => a + b, 0) / n;
      const meanY = y.reduce((a, b) => a + b, 0) / n;
  
      let numerator = 0;
      let sumSqX = 0;
      let sumSqY = 0;
  
      for (let i = 0; i < n; i++) {
        const dx = x[i] - meanX;
        const dy = y[i] - meanY;
        numerator += dx * dy;
        sumSqX += dx * dx;
        sumSqY += dy * dy;
      }
  
      const denominator = Math.sqrt(sumSqX * sumSqY);
  
      if (denominator === 0) {
        return 0;
      }
  
      return numerator / denominator;
    };
  
    const actualDemand = input.actualDemand || [];
    const weatherData = input.weatherData || {};
    const eventData = input.eventData || {};
    const competitorData = input.competitorData || {};
  
    const temperatureCorr = computePearsonCorrelation(
      weatherData.temperature || [],
      actualDemand
    );
    const precipitationCorr = computePearsonCorrelation(
      weatherData.precipitation || [],
      actualDemand
    );
    const isWeekendCorr = computePearsonCorrelation(
      eventData.isWeekend || [],
      actualDemand
    );
    const isSaleCorr = computePearsonCorrelation(
      eventData.isSale || [],
      actualDemand
    );
    const discountRateCorr = computePearsonCorrelation(
      competitorData.discountRate || [],
      actualDemand
    );
    const campaignIntensityCorr = computePearsonCorrelation(
      competitorData.campaignIntensity || [],
      actualDemand
    );
  
    return {
      weatherCorrelation: {
        temperature: Math.round(temperatureCorr * 10000) / 10000,
        precipitation: Math.round(precipitationCorr * 10000) / 10000,
      },
      eventCorrelation: {
        isWeekend: Math.round(isWeekendCorr * 10000) / 10000,
        isSale: Math.round(isSaleCorr * 10000) / 10000,
      },
      competitorCorrelation: {
        discountRate: Math.round(discountRateCorr * 10000) / 10000,
        campaignIntensity: Math.round(campaignIntensityCorr * 10000) / 10000,
      },
      timestamp: new Date().toISOString(),
    };
  }
  return { calculateCorrelationCoefficients };
})();
export const calculateCorrelationCoefficients = __aivicBundle_53_calculateCorrelationCoefficients.calculateCorrelationCoefficients;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateCorrelationCoefficients */

