const __aivicBundle_57_getWeeklyNutritionDashboard = (() => {
  function getWeeklyNutritionDashboard(input: {
    userId: string;
    weekStartDate: string;
    weekEndDate?: string;
    mealRecords?: Array<{
      userId?: string;
      mealDate?: string;
      mealType?: string;
      nutritionItems?: Array<{
        nutrientId: string;
        actualValue: number;
        unit: string;
      }>;
      date?: string;
      mealId?: string;
      nutritionData?: Record<string, number>;
    }>;
    nutritionTargets?: Array<{
      nutrientId: string;
      targetValue: number;
      unit: string;
    }>;
  }): {
    weekStartDate: string;
    weekEndDate?: string;
    nutritionSummary: Array<{
      nutrientId: string;
      totalActualValue: number;
      targetValue: number;
      achievementRate: number;
      gap: number;
      unit: string;
    }>;
    insufficientNutrients: Array<{
      nutrientName: string;
      nutrientId?: string;
      gap: number;
      priority: "high" | "medium" | "low";
    }>;
    excessiveNutrients: Array<{
      nutrientName: string;
      nutrientId?: string;
      excess: number;
    }>;
    overallAchievementRate: number;
  } {
    const { userId, weekStartDate, weekEndDate, mealRecords = [], nutritionTargets = [] } = input;
  
    // Validate required inputs
    if (!userId || !weekStartDate) {
      throw new Error("ユーザーIDと週開始日は必須です");
    }
  
    // Check for data existence
    const hasMealRecords = mealRecords && mealRecords.length > 0;
    const hasNutritionTargets = nutritionTargets && nutritionTargets.length > 0;
  
    if (!hasMealRecords && !hasNutritionTargets) {
      throw new Error("当週のデータが見つかりません");
    }
  
    if (hasMealRecords && !hasNutritionTargets) {
      throw new Error("栄養目標が設定されていません");
    }
  
    if (!hasMealRecords && hasNutritionTargets) {
      throw new Error("当週のデータが見つかりません");
    }
  
    // Build nutrition target map
    const targetMap = new Map<string, { targetValue: number; unit: string }>();
    for (const target of nutritionTargets) {
      targetMap.set(target.nutrientId, {
        targetValue: target.targetValue,
        unit: target.unit,
      });
    }
  
    // Aggregate actual values from meal records
    const actualMap = new Map<string, number>();
    for (const record of mealRecords) {
      const items = record.nutritionItems || [];
      for (const item of items) {
        const current = actualMap.get(item.nutrientId) || 0;
        actualMap.set(item.nutrientId, current + item.actualValue);
      }
    }
  
    // Build nutrition summary
    const nutritionSummary: Array<{
      nutrientId: string;
      totalActualValue: number;
      targetValue: number;
      achievementRate: number;
      gap: number;
      unit: string;
    }> = [];
  
    for (const [nutrientId, target] of targetMap) {
      const actualValue = actualMap.get(nutrientId) || 0;
      const achievementRate = target.targetValue > 0 ? (actualValue / target.targetValue) * 100 : 0;
      const gap = target.targetValue - actualValue;
  
      nutritionSummary.push({
        nutrientId,
        totalActualValue: actualValue,
        targetValue: target.targetValue,
        achievementRate: Math.round(achievementRate * 100) / 100,
        gap,
        unit: target.unit,
      });
    }
  
    // Identify insufficient nutrients (achievement < 100%)
    const insufficientNutrients: Array<{
      nutrientName: string;
      nutrientId?: string;
      gap: number;
      priority: "high" | "medium" | "low";
    }> = [];
  
    for (const item of nutritionSummary) {
      if (item.achievementRate < 100) {
        const gap = Math.max(0, item.gap);
        let priority: "high" | "medium" | "low" = "low";
  
        if (item.achievementRate < 50) {
          priority = "high";
        } else if (item.achievementRate < 75) {
          priority = "medium";
        }
  
        insufficientNutrients.push({
          nutrientName: item.nutrientId,
          nutrientId: item.nutrientId,
          gap,
          priority,
        });
      }
    }
  
    // Sort insufficient nutrients by gap (descending)
    insufficientNutrients.sort((a, b) => b.gap - a.gap);
  
    // Identify excessive nutrients (achievement > 100%)
    const excessiveNutrients: Array<{
      nutrientName: string;
      nutrientId?: string;
      excess: number;
    }> = [];
  
    for (const item of nutritionSummary) {
      if (item.achievementRate > 100) {
        const excess = Math.max(0, item.totalActualValue - item.targetValue);
        excessiveNutrients.push({
          nutrientName: item.nutrientId,
          nutrientId: item.nutrientId,
          excess,
        });
      }
    }
  
    // Calculate overall achievement rate
    const overallAchievementRate =
      nutritionSummary.length > 0
        ? Math.round(
            (nutritionSummary.reduce((sum, item) => sum + item.achievementRate, 0) / nutritionSummary.length) * 100
          ) / 100
        : 0;
  
    return {
      weekStartDate,
      weekEndDate,
      nutritionSummary,
      insufficientNutrients,
      excessiveNutrients,
      overallAchievementRate,
    };
  }
  return { getWeeklyNutritionDashboard };
})();
