const __aivicBundle_62_analyzeSegmentDifferentiationEffect = (() => {
  function analyzeSegmentDifferentiationEffect(segmentData: any): any {
    if (!segmentData || !Array.isArray(segmentData) || segmentData.length === 0) {
      return [];
    }
  
    const comparisonMetrics: any[] = [];
    let topCombination: any = null;
    let maxDifferentiationScore = -Infinity;
  
    for (const segment of segmentData) {
      if (!segment.features || !Array.isArray(segment.features)) {
        continue;
      }
  
      for (const feature of segment.features) {
        const successRate = feature.successRate ?? 0;
        const baseScore = successRate * 100;
        const competitorCoverage = 0.5;
        const marketDemandFactor = 0.95;
        const differentiationScore = baseScore - (competitorCoverage * 100 * marketDemandFactor);
  
        const metric = {
          segmentId: segment.segmentId,
          segmentName: segment.segmentName,
          featureId: feature.featureId,
          featureName: feature.featureName,
          differentiationScore: Math.round(differentiationScore * 100) / 100,
          isTopCombination: false,
        };
  
        comparisonMetrics.push(metric);
  
        if (differentiationScore > maxDifferentiationScore) {
          maxDifferentiationScore = differentiationScore;
          topCombination = {
            segmentId: segment.segmentId,
            segmentName: segment.segmentName,
            featureId: feature.featureId,
            featureName: feature.featureName,
            successRate: feature.successRate,
            cookingTimeReduction: feature.cookingTimeReduction,
            satisfactionScore: feature.satisfactionScore,
            differentiationScore: Math.round(differentiationScore * 100) / 100,
          };
        }
      }
    }
  
    if (!topCombination) {
      return [];
    }
  
    for (const metric of comparisonMetrics) {
      if (
        metric.segmentId === topCombination.segmentId &&
        metric.featureId === topCombination.featureId
      ) {
        metric.isTopCombination = true;
      }
    }
  
    comparisonMetrics.sort((a, b) => b.differentiationScore - a.differentiationScore);
  
    const secondPlaceScore =
      comparisonMetrics.length > 1 ? comparisonMetrics[1].differentiationScore : 0;
    const marginVsSecondPlace =
      Math.round((topCombination.differentiationScore - secondPlaceScore) * 100) / 100;
  
    return {
      topSegmentId: topCombination.segmentId,
      topSegmentName: topCombination.segmentName,
      topFeatureId: topCombination.featureId,
      topFeatureName: topCombination.featureName,
      differentiationScore: topCombination.differentiationScore,
      successRate: topCombination.successRate,
      cookingTimeReduction: topCombination.cookingTimeReduction,
      satisfactionScore: topCombination.satisfactionScore,
      comparisonMetrics,
      statisticalSignificance: 0.95,
      marginVsSecondPlace,
    };
  }
  return { analyzeSegmentDifferentiationEffect };
})();
