const __aivicBundle_96_detectConstraintConflict = (() => {
  function detectConstraintConflict(
    existingConstraints: Record<string, any>,
    newConstraintInput: Record<string, any>
  ): {
    hasConflict: boolean;
    conflictType?: string;
    errorMessage?: string;
    newInputSaved: boolean;
    maintainedReviewContent?: Record<string, any>;
    mergedConstraints?: Record<string, any>;
    recommendedAction?: string;
    rejectedConstraintCount?: number;
  } {
    const reviewStatus = existingConstraints.reviewStatus;
    const isPendingApproval = reviewStatus === "pending_approval";
  
    if (isPendingApproval) {
      const newConstraintKeys = Object.keys(newConstraintInput).filter(
        (key) => key !== "inputTimestamp"
      );
      const rejectedCount = newConstraintKeys.length;
  
      return {
        hasConflict: true,
        conflictType: "pending_review_state",
        errorMessage:
          "レビュー承認待ち中です。追加の制限条件の変更はできません。レビュー完了後に変更してください。",
        newInputSaved: false,
        maintainedReviewContent: {
          calorieLimit: existingConstraints.calorieLimit,
          sodiumLimit: existingConstraints.sodiumLimit,
          reviewStatus: existingConstraints.reviewStatus,
          reviewTimestamp: existingConstraints.reviewTimestamp,
        },
        recommendedAction: "cancel_review_or_wait_approval",
        rejectedConstraintCount: rejectedCount,
      };
    }
  
    if (reviewStatus === "approved" || reviewStatus === "rejected") {
      const mergedConstraints = {
        ...existingConstraints,
      };
  
      const newConstraintKeys = Object.keys(newConstraintInput).filter(
        (key) => key !== "inputTimestamp"
      );
  
      for (const key of newConstraintKeys) {
        mergedConstraints[key] = newConstraintInput[key];
      }
  
      return {
        hasConflict: false,
        newInputSaved: true,
        mergedConstraints,
      };
    }
  
    return {
      hasConflict: false,
      newInputSaved: true,
      mergedConstraints: {
        ...existingConstraints,
        ...newConstraintInput,
      },
    };
  }
  return { detectConstraintConflict };
})();
