const __aivicBundle_100_processMutipleDietaryRestrictions = (() => {
  function processMutipleDietaryRestrictions(input: any): any {
    // Validate required top-level fields
    if (!input || typeof input !== 'object') {
      throw new Error('Input must be an object');
    }
  
    if (input.userId === undefined || input.userId === null) {
      throw new Error('userId is required');
    }
  
    if (input.timestamp === undefined || input.timestamp === null) {
      throw new Error('timestamp is required');
    }
  
    const restrictions = input.restrictions || [];
  
    // Validate each restriction has required fields
    for (const restriction of restrictions) {
      if (restriction.restrictionId === undefined || restriction.restrictionId === null) {
        throw new Error('restrictionId is required for all restrictions');
      }
  
      if (restriction.type === undefined || restriction.type === null) {
        throw new Error('type is required for all restrictions');
      }
  
      if (restriction.value === undefined || restriction.value === null) {
        throw new Error('value is required for all restrictions');
      }
  
      // Validate priority if present: must be a number >= 0
      if (restriction.priority !== undefined && restriction.priority !== null) {
        if (typeof restriction.priority !== 'number' || restriction.priority < 0) {
          throw new Error('priority must be a non-negative number');
        }
      }
    }
  
    // Process restrictions with fallback priority logic
    let fallback_priority_applied = false;
    const processed_restrictions: any[] = [];
    let next_fallback_priority = 1;
  
    for (const restriction of restrictions) {
      const processed: any = {
        restrictionId: restriction.restrictionId,
        type: restriction.type,
        value: restriction.value,
        applied: true,
      };
  
      // Handle priority: if undefined/null, apply fallback; if 0, keep as-is
      if (restriction.priority === undefined || restriction.priority === null) {
        processed.priority = next_fallback_priority;
        next_fallback_priority++;
        fallback_priority_applied = true;
      } else {
        processed.priority = restriction.priority;
      }
  
      processed_restrictions.push(processed);
    }
  
    return {
      success: true,
      restrictions_processed: processed_restrictions,
      fallback_priority_applied,
      processed_count: restrictions.length,
      timestamp: input.timestamp,
    };
  }
  return { processMutipleDietaryRestrictions };
})();
