const __aivicBundle_104_calculateMonthlyCostSummary = (() => {
  function calculateMonthlyCostSummary(input: {
    user_id: string;
    target_month: string;
    transactions: Array<{
      transaction_id?: string;
      user_id?: string;
      transaction_date?: string;
      category: string;
      amount: number;
      description?: string;
    }>;
    budget_limit: number;
  }): {
    total_cost: number;
    difference_from_budget: number;
    is_over_budget: boolean;
    category_breakdown: Record<string, number>;
    target_month: string;
    budget_limit: number;
  } {
    // Validate required input: user_id
    if (!String(input.user_id).trim()) {
      throw new Error("user_id is required");
    }
  
    const { target_month, transactions, budget_limit } = input;
  
    // Calculate total cost from all transactions
    const total_cost = transactions.reduce((sum, tx) => sum + tx.amount, 0);
  
    // Calculate difference from budget (positive = over budget)
    const difference_from_budget = total_cost - budget_limit;
  
    // Determine if over budget
    const is_over_budget = total_cost > budget_limit;
  
    // Build category breakdown
    const category_breakdown: Record<string, number> = {};
    for (const tx of transactions) {
      if (!category_breakdown[tx.category]) {
        category_breakdown[tx.category] = 0;
      }
      category_breakdown[tx.category] += tx.amount;
    }
  
    return {
      total_cost,
      difference_from_budget,
      is_over_budget,
      category_breakdown,
      target_month,
      budget_limit
    };
  }
  return { calculateMonthlyCostSummary };
})();
