const __aivicBundle_105_aggregateMonthlyCostByCategory = (() => {
  function aggregateMonthlyCostByCategory(
    purchaseData: Array<{ date: string; category: string; amount: number; itemName?: string; quantity?: number }>,
    monthYear: string,
    monthlyBudget: number
  ): {
    categoryTotals: { [key: string]: number };
    totalAmount: number;
    budgetReductionRate: number;
    categoryRatios: { [key: string]: number };
    transitionData: Array<{ date: string; category: string; amount: number }>;
    monthYear: string;
  } {
    const categoryTotals: { [key: string]: number } = {};
    const transitionDataList: Array<{ date: string; category: string; amount: number }> = [];
  
    for (const record of purchaseData) {
      const recordDate = record.date;
      const recordMonth = recordDate.substring(0, 7);
  
      if (recordMonth === monthYear) {
        if (!categoryTotals[record.category]) {
          categoryTotals[record.category] = 0;
        }
        categoryTotals[record.category] += record.amount;
  
        transitionDataList.push({
          date: record.date,
          category: record.category,
          amount: record.amount,
        });
      }
    }
  
    const totalAmount = Object.values(categoryTotals).reduce((sum, amount) => sum + amount, 0);
  
    const budgetReductionRate =
      monthlyBudget > 0 ? ((monthlyBudget - totalAmount) / monthlyBudget) * 100 : 0;
  
    const categoryRatios: { [key: string]: number } = {};
    if (totalAmount > 0) {
      for (const [category, amount] of Object.entries(categoryTotals)) {
        categoryRatios[category] = (amount / totalAmount) * 100;
      }
    }
  
    transitionDataList.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  
    return {
      categoryTotals,
      totalAmount,
      budgetReductionRate,
      categoryRatios,
      transitionData: transitionDataList,
      monthYear,
    };
  }
  return { aggregateMonthlyCostByCategory };
})();
