/* AIVIC_FUNCTION_BUNDLE_START owner=aggregateMonthlyCostExpenses exports=aggregateMonthlyCostExpenses */
const __aivicBundle_107_aggregateMonthlyCostExpenses = (() => {
  function aggregateMonthlyCostExpenses(input: {
    userId: string;
    timestamp?: Date;
    expenses: Array<{
      date: string;
      amount: number;
      categoryId?: string;
      category?: string;
      description?: string;
    }>;
    targetMonth?: string;
  }): {
    totalAmount: number;
    month: string;
    expenseCount: number;
    categoryTotals?: { [key: string]: number };
    dailyAverage?: number;
    highestExpenseDay?: { date: string; amount: number };
    lowestExpenseDay?: { date: string; amount: number };
  } {
    if (!String(input.userId).trim()) {
      throw new Error('userId is required');
    }
  
    const { timestamp, expenses, targetMonth } = input;
  
    let filterMonth: string;
    if (targetMonth) {
      filterMonth = targetMonth;
    } else if (timestamp) {
      const year = timestamp.getUTCFullYear();
      const month = String(timestamp.getUTCMonth() + 1).padStart(2, '0');
      filterMonth = `${year}-${month}`;
    } else {
      const now = new Date();
      const year = now.getUTCFullYear();
      const month = String(now.getUTCMonth() + 1).padStart(2, '0');
      filterMonth = `${year}-${month}`;
    }
  
    const filteredExpenses = expenses.filter((expense) => {
      const expenseMonth = expense.date.substring(0, 7);
      return expenseMonth === filterMonth;
    });
  
    const totalAmount = filteredExpenses.reduce((sum, expense) => sum + expense.amount, 0);
  
    const categoryTotals: { [key: string]: number } = {};
    filteredExpenses.forEach((expense) => {
      const category = expense.categoryId || expense.category || 'uncategorized';
      categoryTotals[category] = (categoryTotals[category] || 0) + expense.amount;
    });
  
    const uniqueDates = new Set(filteredExpenses.map((e) => e.date));
    const dailyAverage = uniqueDates.size > 0 ? totalAmount / uniqueDates.size : 0;
  
    let highestExpenseDay: { date: string; amount: number } | undefined;
    let lowestExpenseDay: { date: string; amount: number } | undefined;
  
    if (filteredExpenses.length > 0) {
      const dailyTotals: { [date: string]: number } = {};
      filteredExpenses.forEach((expense) => {
        dailyTotals[expense.date] = (dailyTotals[expense.date] || 0) + expense.amount;
      });
  
      const dates = Object.entries(dailyTotals);
      if (dates.length > 0) {
        const sorted = dates.sort((a, b) => a[1] - b[1]);
        lowestExpenseDay = { date: sorted[0][0], amount: sorted[0][1] };
        highestExpenseDay = { date: sorted[sorted.length - 1][0], amount: sorted[sorted.length - 1][1] };
      }
    }
  
    return {
      totalAmount,
      month: filterMonth,
      expenseCount: filteredExpenses.length,
      categoryTotals,
      dailyAverage,
      highestExpenseDay,
      lowestExpenseDay,
    };
  }
  return { aggregateMonthlyCostExpenses };
})();
