const __aivicBundle_109_identifyInsufficientNutrients = (() => {
  function identifyInsufficientNutrients(
    achievementScores: any[],
    deficiencyThreshold: number
  ): any[] {
    if (!achievementScores || achievementScores.length === 0) {
      return [];
    }
  
    const insufficient = achievementScores
      .filter((score) => score.achievementScore < deficiencyThreshold)
      .sort((a, b) => a.achievementScore - b.achievementScore)
      .map((score, index) => ({
        nutrientId: score.nutrientId,
        nutrientName: score.nutrientName,
        achievementScore: score.achievementScore,
        priority: index + 1,
      }));
  
    return insufficient;
  }
  return { identifyInsufficientNutrients };
})();
