/* AIVIC_FUNCTION_BUNDLE_START owner=calculateImprovementGap exports=calculateImprovementGap */
const __aivicBundle_110_calculateImprovementGap = (() => {
  function calculateImprovementGap(
    nutrientRecords: Array<{
      nutrientId: string;
      nutrientName: string;
      actualValue: number;
      unit: string;
    }>,
    targetStandards: Array<{
      nutrientId: string;
      nutrientName: string;
      targetValue: number;
      unit: string;
    }>
  ): Array<{
    nutrientId: string;
    nutrientName: string;
    gap: number;
    unit: string;
    gapPercentage: number;
  }> {
    const result: Array<{
      nutrientId: string;
      nutrientName: string;
      gap: number;
      unit: string;
      gapPercentage: number;
    }> = [];
  
    for (const record of nutrientRecords) {
      const target = targetStandards.find(
        (t) => t.nutrientId === record.nutrientId
      );
  
      if (!target) {
        continue;
      }
  
      const gap = target.targetValue - record.actualValue;
      const gapPercentage =
        target.targetValue > 0
          ? Math.round((gap / target.targetValue) * 10000) / 100
          : 0;
  
      result.push({
        nutrientId: record.nutrientId,
        nutrientName: record.nutrientName,
        gap: Math.max(0, gap),
        unit: record.unit,
        gapPercentage: Math.max(0, gapPercentage),
      });
    }
  
    return result;
  }
  return { calculateImprovementGap };
})();
