/* AIVIC_FUNCTION_BUNDLE_START owner=visualizeNutritionMetrics exports=visualizeNutritionMetrics */
const __aivicBundle_111_visualizeNutritionMetrics = (() => {
  function visualizeNutritionMetrics(
    achievementScores: any[],
    improvementGaps: any[],
    insufficientNutrients: any[]
  ): {
    summary: {
      totalNutrients: number;
      achievedNutrients: number;
      insufficientNutrients: number;
      averageAchievementScore: number;
    };
    metrics: Array<{
      nutrientId: string;
      nutrientName: string;
      achievementScore: number;
      gap: number;
      gapPercentage: number;
      unit: string;
      status: 'achieved' | 'insufficient';
      displayOrder: number;
    }>;
  } {
    const totalNutrients = achievementScores.length;
    const achievedCount = achievementScores.filter(
      (score) => score.achievementScore >= 100
    ).length;
    const insufficientCount = insufficientNutrients.length;
  
    const averageAchievementScore =
      totalNutrients > 0
        ? Math.round(
            (achievementScores.reduce((sum, score) => sum + score.achievementScore, 0) /
              totalNutrients) *
              100
          ) / 100
        : 0;
  
    const metricsMap = new Map<
      string,
      {
        nutrientId: string;
        nutrientName: string;
        achievementScore: number;
        gap: number;
        gapPercentage: number;
        unit: string;
        status: 'achieved' | 'insufficient';
      }
    >();
  
    achievementScores.forEach((score) => {
      const gap = improvementGaps.find((g) => g.nutrientId === score.nutrientId);
      const isInsufficient = insufficientNutrients.some(
        (n) => n.nutrientId === score.nutrientId
      );
  
      metricsMap.set(score.nutrientId, {
        nutrientId: score.nutrientId,
        nutrientName: score.nutrientName,
        achievementScore: score.achievementScore,
        gap: gap?.gap ?? 0,
        gapPercentage: gap?.gapPercentage ?? 0,
        unit: gap?.unit ?? '',
        status: isInsufficient ? 'insufficient' : 'achieved',
      });
    });
  
    const insufficientPriorityMap = new Map<string, number>();
    insufficientNutrients.forEach((nutrient) => {
      insufficientPriorityMap.set(nutrient.nutrientId, nutrient.priority ?? 0);
    });
  
    const metrics = Array.from(metricsMap.values())
      .map((metric, index) => {
        const priority = insufficientPriorityMap.get(metric.nutrientId) ?? 999;
        return {
          ...metric,
          displayOrder: priority > 0 ? priority : index + 1,
        };
      })
      .sort((a, b) => a.displayOrder - b.displayOrder)
      .map((metric, index) => ({
        ...metric,
        displayOrder: index + 1,
      }));
  
    return {
      summary: {
        totalNutrients,
        achievedNutrients: achievedCount,
        insufficientNutrients: insufficientCount,
        averageAchievementScore,
      },
      metrics,
    };
  }
  return { visualizeNutritionMetrics };
})();
export const visualizeNutritionMetrics = __aivicBundle_111_visualizeNutritionMetrics.visualizeNutritionMetrics;
