/* AIVIC_FUNCTION_BUNDLE_START owner=analyzeMonthlyExpenseExcess exports=analyzeMonthlyExpenseExcess */
const __aivicBundle_115_analyzeMonthlyExpenseExcess = (() => {
  function analyzeMonthlyExpenseExcess(input: {
    userId: string;
    targetMonth: string;
    monthlyBudget?: number;
    expenseRecords: Array<{
      id: string;
      userId: string;
      date: string;
      amount: number;
      category: string;
      aggregatedFlag: boolean;
    }>;
  }): {
    userId: string;
    targetMonth: string;
    totalExpense: number;
    monthlyBudget?: number;
    excessAmount: number;
    isExceeded: boolean;
    categoryBreakdown: Record<string, number>;
    unitPriceVariationAnalysis?: {
      averageUnitPrice: number;
      priceChangePercentage: number;
    };
  } {
    const { userId, targetMonth, monthlyBudget, expenseRecords } = input;
  
    // Validation: Check if expenseRecords is empty
    if (!expenseRecords || expenseRecords.length === 0) {
      throw new Error(`月次集計データが見つかりません: ${targetMonth}`);
    }
  
    // Validation: Check if all records have aggregatedFlag === true
    const allAggregated = expenseRecords.every((record) => record.aggregatedFlag === true);
  
    if (!allAggregated) {
      throw new Error(`月次集計されていないデータが含まれています: ${targetMonth}`);
    }
  
    // Calculate total expense by category
    const categoryBreakdown: Record<string, number> = {};
    let totalExpense = 0;
  
    for (const record of expenseRecords) {
      const category = record.category;
      if (!categoryBreakdown[category]) {
        categoryBreakdown[category] = 0;
      }
      categoryBreakdown[category] += record.amount;
      totalExpense += record.amount;
    }
  
    // Calculate excess
    const budget = monthlyBudget ?? 0;
    const excessAmount = Math.max(0, totalExpense - budget);
    const isExceeded = totalExpense > budget;
  
    const result: {
      userId: string;
      targetMonth: string;
      totalExpense: number;
      monthlyBudget?: number;
      excessAmount: number;
      isExceeded: boolean;
      categoryBreakdown: Record<string, number>;
      unitPriceVariationAnalysis?: {
        averageUnitPrice: number;
        priceChangePercentage: number;
      };
    } = {
      userId,
      targetMonth,
      totalExpense,
      excessAmount,
      isExceeded,
      categoryBreakdown,
    };
  
    if (monthlyBudget !== undefined) {
      result.monthlyBudget = monthlyBudget;
    }
  
    // Add unitPriceVariationAnalysis if there are records
    if (expenseRecords.length > 0) {
      const averageUnitPrice = totalExpense / expenseRecords.length;
      result.unitPriceVariationAnalysis = {
        averageUnitPrice,
        priceChangePercentage: 0,
      };
    }
  
    return result;
  }
  return { analyzeMonthlyExpenseExcess };
})();
export const analyzeMonthlyExpenseExcess = __aivicBundle_115_analyzeMonthlyExpenseExcess.analyzeMonthlyExpenseExcess;
/* AIVIC_FUNCTION_BUNDLE_END owner=analyzeMonthlyExpenseExcess */

/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionAchievementAndGapAnalysis exports=calculateNutritionAchievementAndGapAnalysis */
const __aivicBundle_116_calculateNutritionAchievementAndGapAnalysis = (() => {
  function calculateNutritionAchievementAndGapAnalysis(input: {
    foodPurchaseRecords: Array<{
      foodId: string;
      foodName: string;
      unitPrice: number;
      quantity: number;
      totalCost: number;
      purchaseDate: string;
    }>;
    monthlyBudget: number;
    nutritionTargets: Record<string, number>;
    actualNutritionIntake: Record<string, number>;
  }): {
    abnormalValueDetection: Array<{
      foodId: string;
      severity: 'warning' | 'error';
      message: string;
    }>;
    validFoodRecords: Array<{
      foodId: string;
      foodName: string;
      unitPrice: number;
      quantity: number;
      totalCost: number;
      purchaseDate: string;
    }>;
    validTotalCost: number;
    budgetOverageFlag: boolean;
    budgetRemainAmount: number;
    nutritionAchievementRates: Record<string, number>;
    nutritionGaps: Record<string, number>;
    prioritizedGaps: Array<{
      nutrientName: string;
      achievementRate: number;
      gap: number;
      priority: number;
    }>;
    processingLog: Array<{
      timestamp: string;
      message: string;
      severity: 'info' | 'warning' | 'error';
    }>;
    trustworthyScore: number;
    analysisStatus: string;
    userNotification: string;
  } {
    const abnormalValueDetection: Array<{
      foodId: string;
      severity: 'warning' | 'error';
      message: string;
    }> = [];
    const processingLog: Array<{
      timestamp: string;
      message: string;
      severity: 'info' | 'warning' | 'error';
    }> = [];
  
    const now = new Date().toISOString();
  
    // Step 1: Detect abnormal values in food purchase records
    const validFoodRecords = input.foodPurchaseRecords.filter((record) => {
      if (record.unitPrice === 0) {
        abnormalValueDetection.push({
          foodId: record.foodId,
          severity: 'warning',
          message: `食材 ${record.foodName} の単価が0円です。`,
        });
        processingLog.push({
          timestamp: now,
          message: `食材 ${record.foodId} (${record.foodName}) の単価が0円として検出されました。`,
          severity: 'warning',
        });
        return false;
      }
  
      if (record.unitPrice < 0) {
        abnormalValueDetection.push({
          foodId: record.foodId,
          severity: 'error',
          message: `食材 ${record.foodName} の単価が負数です。`,
        });
        processingLog.push({
          timestamp: now,
          message: `食材 ${record.foodId} (${record.foodName}) の単価が負数として検出されました。`,
          severity: 'error',
        });
        return false;
      }
  
      if (record.unitPrice > 10000000) {
        abnormalValueDetection.push({
          foodId: record.foodId,
          severity: 'error',
          message: `食材 ${record.foodName} の単価が異常値です。`,
        });
        processingLog.push({
          timestamp: now,
          message: `食材 ${record.foodId} (${record.foodName}) の単価が異常値として検出されました。`,
          severity: 'error',
        });
        return false;
      }
  
      return true;
    });
  
    // Step 2: Calculate valid total cost
    const validTotalCost = validFoodRecords.reduce(
      (sum, record) => sum + record.totalCost,
      0
    );
  
    // Step 3: Calculate budget overage
    const budgetOverageFlag = validTotalCost > input.monthlyBudget;
    const budgetRemainAmount = input.monthlyBudget - validTotalCost;
  
    processingLog.push({
      timestamp: now,
      message: `有効食材の総食費: ${validTotalCost}円、予算: ${input.monthlyBudget}円`,
      severity: 'info',
    });
  
    // Step 4: Calculate nutrition achievement rates and gaps
    const nutritionAchievementRates: Record<string, number> = {};
    const nutritionGaps: Record<string, number> = {};
  
    Object.entries(input.nutritionTargets).forEach(([nutrient, target]) => {
      const actual = input.actualNutritionIntake[nutrient] || 0;
      const achievementRate = (actual / target) * 100;
      const gap = target - actual;
  
      nutritionAchievementRates[nutrient] = Math.round(achievementRate * 100) / 100;
      nutritionGaps[nutrient] = gap;
    });
  
    // Step 5: Prioritize gaps (lower achievement rate = higher priority)
    const prioritizedGaps = Object.entries(nutritionGaps)
      .map(([nutrient, gap]) => ({
        nutrientName: nutrient,
        achievementRate: nutritionAchievementRates[nutrient],
        gap: gap,
        priority: 0,
      }))
      .sort((a, b) => a.achievementRate - b.achievementRate)
      .map((item, index) => ({
        ...item,
        priority: index + 1,
      }));
  
    // Step 6: Calculate trustworthy score
    const totalRecords = input.foodPurchaseRecords.length;
    const validRecords = validFoodRecords.length;
    const trustworthyScore =
      totalRecords > 0 ? (validRecords / totalRecords) * 100 : 100;
  
    // Step 7: Determine analysis status
    const analysisStatus =
      abnormalValueDetection.length > 0
        ? 'completed_with_warnings'
        : 'completed';
  
    // Step 8: Generate user notification
    const abnormalCount = abnormalValueDetection.length;
    const userNotification =
      abnormalCount > 0
        ? `分析完了: ${abnormalCount}件の異常値が検出されました。有効なデータ${validRecords}件のみを使用して分析を実施しました。`
        : `分析完了: 有効なデータ${validRecords}件で分析を実施しました。`;
  
    return {
      abnormalValueDetection,
      validFoodRecords,
      validTotalCost,
      budgetOverageFlag,
      budgetRemainAmount,
      nutritionAchievementRates,
      nutritionGaps,
      prioritizedGaps,
      processingLog,
      trustworthyScore: Math.round(trustworthyScore * 100) / 100,
      analysisStatus,
      userNotification,
    };
  }
  return { calculateNutritionAchievementAndGapAnalysis };
})();
export const calculateNutritionAchievementAndGapAnalysis = __aivicBundle_116_calculateNutritionAchievementAndGapAnalysis.calculateNutritionAchievementAndGapAnalysis;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutritionAchievementAndGapAnalysis */

/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeNutrientDeficiencies exports=prioritizeNutrientDeficiencies */
const __aivicBundle_117_prioritizeNutrientDeficiencies = (() => {
  interface PrioritizedNutrientDeficiency {
    nutrient_id: number;
    nutrient_name: string;
    target_value: number;
    actual_value: number;
    unit: string;
    deficiency_gap: number;
    family_preference_score: number;
    improvement_effect_score: number;
    priority_score: number;
    priority_rank: number;
  }
  
   function prioritizeNutrientDeficiencies(
    nutrientDeficiencies: Array<{
      nutrient_id: number;
      nutrient_name: string;
      target_value: number;
      actual_value: number;
      unit: string;
      deficiency_gap: number;
      family_preference_score: number;
    }>
  ): PrioritizedNutrientDeficiency[] {
    if (!nutrientDeficiencies || nutrientDeficiencies.length === 0) {
      return [];
    }
  
    const scored = nutrientDeficiencies.map((item) => {
      const deficiencyPercentage =
        (item.deficiency_gap / item.target_value) * 100;
  
      const improvementEffectScore = deficiencyPercentage;
  
      const preferenceRisk = (1 - item.family_preference_score) * 100;
  
      const priorityScore =
        improvementEffectScore * 0.7 + (100 - preferenceRisk) * 0.3;
  
      return {
        ...item,
        improvement_effect_score: Math.round(improvementEffectScore * 100) / 100,
        priority_score: Math.round(priorityScore * 100) / 100,
        priority_rank: 0,
      };
    });
  
    scored.sort((a, b) => b.priority_score - a.priority_score);
  
    const result: PrioritizedNutrientDeficiency[] = scored.map(
      (item, index) => ({
        ...item,
        priority_rank: index + 1,
      })
    );
  
    return result;
  }
  return { prioritizeNutrientDeficiencies };
})();
export const prioritizeNutrientDeficiencies = __aivicBundle_117_prioritizeNutrientDeficiencies.prioritizeNutrientDeficiencies;
