/* AIVIC_FUNCTION_BUNDLE_START owner=prioritizeNutritionDeficiencies exports=prioritizeNutritionDeficiencies */
const __aivicBundle_118_prioritizeNutritionDeficiencies = (() => {
  function prioritizeNutritionDeficiencies(
    input: any
  ): Array<{
    nutrientId: string;
    nutrientName: string;
    targetValue: number;
    actualValue: number;
    achievementRate: number;
    improvementGap: number;
    priorityScore: number;
  }> {
    // Handle null or empty input
    if (input === null || input === undefined) {
      return [];
    }
  
    // Handle empty array
    if (Array.isArray(input) && input.length === 0) {
      return [];
    }
  
    // Handle object with insufficientItems property
    if (
      typeof input === 'object' &&
      !Array.isArray(input) &&
      'insufficientItems' in input
    ) {
      if (input.insufficientItems === null || input.totalCount === 0) {
        return [];
      }
    }
  
    // Convert to array if not already
    let items: any[] = Array.isArray(input) ? input : [];
  
    // Filter out items with invalid improvementEffectScore
    const validItems = items.filter((item) => {
      const score = item.improvementEffectScore;
  
      // Check for null or undefined
      if (score === null || score === undefined) {
        throw new Error('改善効果スコアが無効です');
      }
  
      // Check for NaN
      if (typeof score === 'number' && isNaN(score)) {
        throw new Error('改善効果スコアが無効です');
      }
  
      // Check for negative values
      if (typeof score === 'number' && score < 0) {
        throw new Error('改善効果スコアが無効です');
      }
  
      // Check for non-numeric values
      if (typeof score !== 'number') {
        throw new Error('改善効果スコアが無効です');
      }
  
      return true;
    });
  
    // Sort by improvementEffectScore in descending order
    const sorted = validItems.sort(
      (a, b) => b.improvementEffectScore - a.improvementEffectScore
    );
  
    // Map to output format
    const result = sorted.map((item) => ({
      nutrientId: item.nutrientId,
      nutrientName: item.nutrientName,
      targetValue: item.targetValue,
      actualValue: item.actualValue,
      achievementRate: item.achievementRate,
      improvementGap: item.improvementGap || item.targetValue - item.actualValue,
      priorityScore: item.improvementEffectScore,
    }));
  
    return result;
  }
  return { prioritizeNutritionDeficiencies };
})();
export const prioritizeNutritionDeficiencies: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_118_prioritizeNutritionDeficiencies.prioritizeNutritionDeficiencies as (...args: any[]) => any)(...args);
/* AIVIC_FUNCTION_BUNDLE_END owner=prioritizeNutritionDeficiencies */

/* AIVIC_FUNCTION_BUNDLE_START owner=decideMealPriorityConditionSet exports=decideMealPriorityConditionSet */
const __aivicBundle_119_decideMealPriorityConditionSet = (() => {
  function decideMealPriorityConditionSet(
    monthlyAnalysisData: {
      month: string;
      budgetLimit: number;
      actualExpense: number;
      budgetExceededAmount: number;
      budgetExceededRate: number;
      nutritionItems: Array<{
        nutrientId: string;
        nutrientName: string;
        recommendedValue: number;
        actualValue: number;
        achievementRate: number;
        gapValue: number;
        priority: number;
      }>;
      insufficientNutrientCount: number;
      deficitNutrientIds: string[];
    }
  ): {
    priorityConditionSetType: string;
    costOptimizationWeight: number;
    nutritionSupplementWeight: number;
    costOptimizationConditions: {
      targetReductionRate: number;
      preferSeasonal: boolean;
      preferBulkPurchase: boolean;
      allowDiscountItems: boolean;
      maxCostPerMeal: number;
    };
    nutritionSupplementConditions: {
      priorityNutrients: string[];
      targetProteinIncrease: number;
      targetCalciumIncrease: number;
      targetIronIncrease: number;
      supplementFoodCategories: string[];
    };
    mealGenerationPriority: {
      order: number;
      nutrientBalanceWeight: number;
      costOptimizationWeight: number;
      familyPreferenceWeight: number;
    };
    decisionTimestamp: string;
    analysisMonth: string;
    decisionReason: string;
  } {
    // Validate required input: actualExpense must be used in calculation
    if (
      monthlyAnalysisData.actualExpense === undefined ||
      monthlyAnalysisData.actualExpense === null
    ) {
      throw new Error("actualExpense is required");
    }
  
    const isOverBudget = monthlyAnalysisData.budgetExceededAmount > 0;
    const hasNutritionDeficit = monthlyAnalysisData.insufficientNutrientCount > 0;
  
    const decisionTimestamp = new Date().toISOString();
    const analysisMonth = monthlyAnalysisData.month;
  
    // Calculate maxCostPerMeal based on actual budget limit and actual expense
    const maxCostPerMeal = Math.round(
      (monthlyAnalysisData.budgetLimit / 30) * 100
    ) / 100;
  
    // Extract priority nutrients sorted by priority
    const priorityNutrients = monthlyAnalysisData.nutritionItems
      .sort((a, b) => a.priority - b.priority)
      .map((item) => item.nutrientId);
  
    // Calculate target increases for each nutrient
    const proteinItem = monthlyAnalysisData.nutritionItems.find(
      (item) => item.nutrientId === "protein"
    );
    const calciumItem = monthlyAnalysisData.nutritionItems.find(
      (item) => item.nutrientId === "calcium"
    );
    const ironItem = monthlyAnalysisData.nutritionItems.find(
      (item) => item.nutrientId === "iron"
    );
  
    const targetProteinIncrease = proteinItem ? proteinItem.gapValue : 0;
    const targetCalciumIncrease = calciumItem ? calciumItem.gapValue : 0;
    const targetIronIncrease = ironItem ? ironItem.gapValue : 0;
  
    // Food expense is used to determine strategy: if over budget and nutrition deficit exists
    const expenseRatio = monthlyAnalysisData.actualExpense / monthlyAnalysisData.budgetLimit;
  
    // Determine decision reason based on actual expense and budget relationship
    let decisionReason = "通常の献立生成を実施";
    if (isOverBudget && hasNutritionDeficit) {
      decisionReason = "食費超過と栄養不足の同時解決が必要";
    } else if (isOverBudget && expenseRatio > 1.0) {
      decisionReason = "食費超過の改善が必要";
    } else if (hasNutritionDeficit) {
      decisionReason = "栄養不足の改善が必要";
    }
  
    // When both over budget and nutrition deficit: balanced strategy
    if (isOverBudget && hasNutritionDeficit) {
      const targetReductionRate = monthlyAnalysisData.budgetExceededRate;
  
      return {
        priorityConditionSetType: "balanced",
        costOptimizationWeight: 50,
        nutritionSupplementWeight: 50,
        costOptimizationConditions: {
          targetReductionRate,
          preferSeasonal: true,
          preferBulkPurchase: true,
          allowDiscountItems: true,
          maxCostPerMeal,
        },
        nutritionSupplementConditions: {
          priorityNutrients,
          targetProteinIncrease,
          targetCalciumIncrease,
          targetIronIncrease,
          supplementFoodCategories: ["lean_meat", "dairy", "fish"],
        },
        mealGenerationPriority: {
          order: 1,
          nutrientBalanceWeight: 40,
          costOptimizationWeight: 40,
          familyPreferenceWeight: 20,
        },
        decisionTimestamp,
        analysisMonth,
        decisionReason,
      };
    }
  
    // Default: balanced optimization when no overage or no deficit
    return {
      priorityConditionSetType: "balanced",
      costOptimizationWeight: 50,
      nutritionSupplementWeight: 50,
      costOptimizationConditions: {
        targetReductionRate: 0,
        preferSeasonal: true,
        preferBulkPurchase: true,
        allowDiscountItems: true,
        maxCostPerMeal,
      },
      nutritionSupplementConditions: {
        priorityNutrients: monthlyAnalysisData.deficitNutrientIds,
        targetProteinIncrease,
        targetCalciumIncrease,
        targetIronIncrease,
        supplementFoodCategories: ["lean_meat", "dairy", "fish"],
      },
      mealGenerationPriority: {
        order: 1,
        nutrientBalanceWeight: 40,
        costOptimizationWeight: 40,
        familyPreferenceWeight: 20,
      },
      decisionTimestamp,
      analysisMonth,
      decisionReason,
    };
  }
  return { decideMealPriorityConditionSet };
})();
export const decideMealPriorityConditionSet = __aivicBundle_119_decideMealPriorityConditionSet.decideMealPriorityConditionSet;
/* AIVIC_FUNCTION_BUNDLE_END owner=decideMealPriorityConditionSet */

/* AIVIC_FUNCTION_BUNDLE_START owner=determineMenuPriorityConditionSet exports=determineMenuPriorityConditionSet */
const __aivicBundle_120_determineMenuPriorityConditionSet = (() => {
  interface DetermineMenuPriorityConditionSetInput {
    userId: string;
    analysisMonth: string;
    foodBudgetLimit: number;
    foodActualAmount: number;
    budgetExcessFlag: boolean;
    nutritionAchievementData: Array<{
      nutrientName: string;
      recommendedValue: number;
      actualValue: number;
      achievementRatePercent: number;
      achievementStatus: string;
    }>;
    allNutrientsFulfilledFlag: boolean;
    insufficientNutrientCount: number;
  }
  
  interface DetermineMenuPriorityConditionSetOutput {
    priorityConditionSetType: string;
    priorityConditionSetDetails: {
      priorityFocus: string;
      budgetOptimization: string;
      noveltyIntroduction: string;
      familyPreferenceWeight: number;
      nutritionalBalanceWeight: number;
      budgetWeight: number;
      menuDiversityLevel: string;
      costOptimizationLevel: string;
      additionalConstraints: string[];
    };
    decisionReason: {
      budgetStatus: string;
      budgetDifferenceAmount: number;
      budgetDifferencePercent: number;
      nutritionStatus: string;
      insufficientNutrients: string[];
      recommendedAction: string;
    };
    decisionScore: {
      budgetAdherenceScore: number;
      nutritionFulfillmentScore: number;
      overallDecisionConfidenceScore: number;
    };
    decidedAt: string;
    validFrom: string;
    validUntil: string;
    status: string;
    decisionId: string;
  }
  
   function determineMenuPriorityConditionSet(
    input: DetermineMenuPriorityConditionSetInput
  ): DetermineMenuPriorityConditionSetOutput {
    // Validate required userId
    if (!String(input.userId).trim()) {
      throw new Error("userId is required");
    }
  
    const {
      analysisMonth,
      foodBudgetLimit,
      foodActualAmount,
      budgetExcessFlag,
      nutritionAchievementData,
      allNutrientsFulfilledFlag,
      insufficientNutrientCount,
    } = input;
  
    // 予算差分の計算
    const budgetDifferenceAmount = foodBudgetLimit - foodActualAmount;
    const budgetDifferencePercent =
      foodBudgetLimit > 0
        ? (budgetDifferenceAmount / foodBudgetLimit) * 100
        : 0;
  
    // 予算遵守スコア（実績 / 予算 * 100）
    const budgetAdherenceScore =
      foodBudgetLimit > 0
        ? (foodActualAmount / foodBudgetLimit) * 100
        : 0;
  
    // 栄養充足スコア（全栄養素の達成率の平均）
    const nutritionFulfillmentScore =
      nutritionAchievementData && nutritionAchievementData.length > 0
        ? Math.round(
            (nutritionAchievementData.reduce(
              (sum: number, item: any) =>
                sum + (item.achievementRatePercent || 0),
              0
            ) /
              nutritionAchievementData.length) *
              10
          ) / 10
        : 0;
  
    // 総合信度スコア（予算超過なし＆全栄養充足で高信度）
    const overallDecisionConfidenceScore =
      !budgetExcessFlag && allNutrientsFulfilledFlag
        ? 99.5
        : Math.max(50, 80 - insufficientNutrientCount * 10);
  
    // 優先条件セットタイプの決定
    const priorityConditionSetType =
      !budgetExcessFlag && allNutrientsFulfilledFlag
        ? "maintenance"
        : budgetExcessFlag && insufficientNutrientCount > 0
          ? "cost_and_nutrition_improvement"
          : budgetExcessFlag
            ? "cost_reduction"
            : "nutrition_improvement";
  
    // 優先条件セット詳細の決定
    const priorityConditionSetDetails =
      priorityConditionSetType === "maintenance"
        ? {
            priorityFocus: "nutritional_balance_maintenance",
            budgetOptimization: "relaxed",
            noveltyIntroduction: "low",
            familyPreferenceWeight: 0.6,
            nutritionalBalanceWeight: 0.3,
            budgetWeight: 0.1,
            menuDiversityLevel: "standard",
            costOptimizationLevel: "none",
            additionalConstraints: [],
          }
        : priorityConditionSetType === "cost_reduction"
          ? {
              priorityFocus: "cost_reduction",
              budgetOptimization: "aggressive",
              noveltyIntroduction: "minimal",
              familyPreferenceWeight: 0.3,
              nutritionalBalanceWeight: 0.4,
              budgetWeight: 0.3,
              menuDiversityLevel: "low",
              costOptimizationLevel: "high",
              additionalConstraints: ["exclude_premium_ingredients"],
            }
          : priorityConditionSetType === "nutrition_improvement"
            ? {
                priorityFocus: "nutritional_deficiency_improvement",
                budgetOptimization: "moderate",
                noveltyIntroduction: "medium",
                familyPreferenceWeight: 0.4,
                nutritionalBalanceWeight: 0.5,
                budgetWeight: 0.1,
                menuDiversityLevel: "medium",
                costOptimizationLevel: "low",
                additionalConstraints: ["focus_on_deficient_nutrients"],
              }
            : {
                priorityFocus: "balanced_cost_and_nutrition",
                budgetOptimization: "moderate",
                noveltyIntroduction: "medium",
                familyPreferenceWeight: 0.4,
                nutritionalBalanceWeight: 0.4,
                budgetWeight: 0.2,
                menuDiversityLevel: "medium",
                costOptimizationLevel: "moderate",
                additionalConstraints: [],
              };
  
    // 不足栄養素の抽出
    const insufficientNutrients =
      nutritionAchievementData && nutritionAchievementData.length > 0
        ? nutritionAchievementData
            .filter(
              (item: any) =>
                item.achievementRatePercent < 100 &&
                item.achievementStatus !== "達成"
            )
            .map((item: any) => item.nutrientName)
        : [];
  
    // 決定根拠メタデータ
    const decisionReason = {
      budgetStatus: budgetExcessFlag ? "exceeded" : "within_limit",
      budgetDifferenceAmount,
      budgetDifferencePercent,
      nutritionStatus: allNutrientsFulfilledFlag
        ? "all_fulfilled"
        : "has_deficiencies",
      insufficientNutrients,
      recommendedAction:
        priorityConditionSetType === "maintenance"
          ? "maintain_current_menu_balance"
          : priorityConditionSetType === "cost_reduction"
            ? "reduce_cost_while_maintaining_nutrition"
            : priorityConditionSetType === "nutrition_improvement"
              ? "improve_nutritional_deficiencies"
              : "balance_cost_and_nutrition",
    };
  
    // 意思決定スコア
    const decisionScore = {
      budgetAdherenceScore,
      nutritionFulfillmentScore,
      overallDecisionConfidenceScore,
    };
  
    // 分析月から次月の有効期限を計算
    const analysisDate = new Date(analysisMonth);
    const nextMonth = new Date(analysisDate);
    nextMonth.setMonth(nextMonth.getMonth() + 1);
  
    const validFromDate = new Date(nextMonth);
    validFromDate.setDate(1);
    validFromDate.setHours(0, 0, 0, 0);
  
    const validUntilDate = new Date(nextMonth);
    validUntilDate.setMonth(validUntilDate.getMonth() + 1);
    validUntilDate.setDate(0);
    validUntilDate.setHours(23, 59, 59, 999);
  
    // 決定ID生成（UUID）
    const decisionId = randomUUID();
  
    // 処理時刻を取得
    const decidedAtTime = new Date().toISOString();
  
    return {
      priorityConditionSetType,
      priorityConditionSetDetails,
      decisionReason,
      decisionScore,
      decidedAt: decidedAtTime,
      validFrom: validFromDate.toISOString().replace(/\.\d{3}Z$/, "Z"),
      validUntil: validUntilDate.toISOString().replace(/\.\d{3}Z$/, "Z"),
      status: "determined",
      decisionId,
    };
  }
  return { determineMenuPriorityConditionSet };
})();
export const determineMenuPriorityConditionSet = __aivicBundle_120_determineMenuPriorityConditionSet.determineMenuPriorityConditionSet;
