/* AIVIC_FUNCTION_BUNDLE_START owner=validateMonthlyAnalysisCycleDuration exports=validateMonthlyAnalysisCycleDuration */
const __aivicBundle_128_validateMonthlyAnalysisCycleDuration = (() => {
  function validateMonthlyAnalysisCycleDuration(input: {
    cycleDurationDays: number;
    analysisStartDate: Date;
    analysisEndDate: Date;
  }): CycleDurationValidation {
    const startDate = new Date(input.analysisStartDate);
    const endDate = new Date(input.analysisEndDate);
  
    // 実際の期間を日数で計算（開始日を含む）
    const actualDurationDays =
      Math.floor((endDate.getTime() - startDate.getTime()) / (1000 * 60 * 60 * 24)) + 1;
  
    // 期待される期間（cycleDurationDays）
    const expectedDurationDays = input.cycleDurationDays;
  
    // SLA 閾値は 7 日
    const slaThresholdDays = 7;
  
    // 超過日数を計算
    const exceedsDays = Math.max(0, actualDurationDays - slaThresholdDays);
  
    // 警告フラグ：実際の期間が SLA 閾値を超えた場合
    const warningFlag = actualDurationDays > slaThresholdDays;
  
    // 警告メッセージの生成
    let warningMessage = "";
    if (warningFlag) {
      warningMessage = `分析サイクルが7日を超過しています。超過日数: ${exceedsDays}日`;
    }
  
    // 検証結果の判定
    const isValid = actualDurationDays <= slaThresholdDays;
    const durationStatus = isValid ? "within_sla" : "exceeded_sla";
  
    return {
      isValid,
      actualDurationDays,
      expectedDurationDays,
      durationStatus,
      validationMessage: warningMessage || "分析サイクルは SLA 内です",
      warningFlag,
      exceedsDays,
      warningMessage,
    };
  }
  
  interface CycleDurationValidation {
    isValid: boolean;
    actualDurationDays: number;
    expectedDurationDays: number;
    durationStatus: "within_sla" | "exceeded_sla";
    validationMessage: string;
    warningFlag: boolean;
    exceedsDays: number;
    warningMessage: string;
  }
  return { validateMonthlyAnalysisCycleDuration };
})();
