/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNextVerificationDate exports=calculateNextVerificationDate */
const __aivicBundle_136_calculateNextVerificationDate = (() => {
  function calculateNextVerificationDate(
    lastVerificationDate: Date | null,
    cycle: string | undefined
  ): Date {
    if (lastVerificationDate === null || lastVerificationDate === undefined) {
      throw new Error('前回検証日が指定されていません');
    }
  
    if (cycle === undefined || cycle === null || typeof cycle !== 'string') {
      throw new Error('検証周期が指定されていません');
    }
  
    if (cycle !== 'monthly') {
      throw new Error('無効な検証周期です');
    }
  
    const date = new Date(lastVerificationDate);
    const year = date.getUTCFullYear();
    const month = date.getUTCMonth();
    const day = date.getUTCDate();
  
    let nextYear = year;
    let nextMonth = month + 1;
  
    if (nextMonth > 11) {
      nextMonth = 0;
      nextYear += 1;
    }
  
    let nextDay = day;
    const daysInNextMonth = new Date(Date.UTC(nextYear, nextMonth + 1, 0)).getUTCDate();
  
    if (nextDay > daysInNextMonth) {
      nextDay = daysInNextMonth;
    }
  
    return new Date(Date.UTC(nextYear, nextMonth, nextDay, 0, 0, 0, 0));
  }
  return { calculateNextVerificationDate };
})();
