/* AIVIC_FUNCTION_BUNDLE_START owner=determineVerificationTiming exports=determineVerificationTiming */
const __aivicBundle_137_determineVerificationTiming = (() => {
  function determineVerificationTiming(input: {
    verification_cycle_days: number;
    last_verification_date: Date;
    current_date: Date;
  }): {
    is_verification_timing_arrived: boolean;
    next_verification_scheduled_date: Date;
    alert_message: string;
  } {
    const { verification_cycle_days, last_verification_date, current_date } = input;
  
    const lastVerificationTime = last_verification_date.getTime();
    const currentTime = current_date.getTime();
    const cycleDurationMs = verification_cycle_days * 24 * 60 * 60 * 1000;
  
    const elapsedTime = currentTime - lastVerificationTime;
    const isVerificationTimingArrived = elapsedTime >= cycleDurationMs;
  
    const nextVerificationTime = lastVerificationTime + cycleDurationMs;
    const nextVerificationScheduledDate = new Date(nextVerificationTime);
  
    const alertMessage = isVerificationTimingArrived
      ? `検証周期${verification_cycle_days}日が経過しました。検証を実施してください。`
      : `次回検証予定日は${nextVerificationScheduledDate.toISOString().split('T')[0]}です。`;
  
    return {
      is_verification_timing_arrived: isVerificationTimingArrived,
      next_verification_scheduled_date: nextVerificationScheduledDate,
      alert_message: alertMessage,
    };
  }
  return { determineVerificationTiming };
})();
