const __aivicBundle_138_determineNextVerificationDate = (() => {
  interface DetermineNextVerificationDateInput {
    current_date: Date;
    previous_verification_date: Date | null;
    verification_cycle_days: number;
  }
  
  interface DetermineNextVerificationDateResult {
    next_verification_date: Date;
    is_verification_due: boolean;
    days_until_verification: number;
    should_collect_user_data: boolean;
  }
  
   function determineNextVerificationDate(
    input: DetermineNextVerificationDateInput
  ): DetermineNextVerificationDateResult {
    const { current_date, previous_verification_date, verification_cycle_days } = input;
  
    if (verification_cycle_days <= 0) {
      throw new Error('検証周期は正の整数である必要があります');
    }
  
    let next_verification_date: Date;
  
    if (previous_verification_date === null) {
      next_verification_date = new Date(current_date);
      next_verification_date.setDate(
        next_verification_date.getDate() + verification_cycle_days
      );
    } else {
      next_verification_date = new Date(previous_verification_date);
      next_verification_date.setDate(
        next_verification_date.getDate() + verification_cycle_days
      );
    }
  
    const time_diff_ms = next_verification_date.getTime() - current_date.getTime();
    const days_until_verification = Math.ceil(time_diff_ms / (1000 * 60 * 60 * 24));
  
    const is_verification_due = days_until_verification <= 0;
    const should_collect_user_data = is_verification_due;
  
    return {
      next_verification_date,
      is_verification_due,
      days_until_verification,
      should_collect_user_data,
    };
  }
  return { determineNextVerificationDate };
})();
