/* AIVIC_FUNCTION_BUNDLE_START owner=instructDataCollection exports=instructDataCollection */
const __aivicBundle_140_instructDataCollection = (() => {
  interface InstructDataCollectionInput {
    config?: {
      verificationCycleType?: string;
      verificationScheduleTime?: string;
      collectionPeriodDays?: number;
      minimumSampleCount?: number;
      userId?: string;
      familyMemberId?: string;
    };
    currentTime?: Date;
    minimum_sample_count?: number;
    available_sample_count?: number;
    collection_period?: string;
  }
  
  interface InstructDataCollectionResult {
    collectionPeriodDays: number;
    minimumSampleCount: number;
    collectionStartDate: Date;
    collectionEndDate: Date;
    collectionStatus: string;
    userId: string;
    familyMemberId: string;
    instructionIssuedAt: Date;
    nextVerificationScheduledTime: Date;
  }
  
   function instructDataCollection(
    input: InstructDataCollectionInput
  ): InstructDataCollectionResult {
    // Handle snake_case validation input (SCEN-463)
    if (
      input.minimum_sample_count !== undefined &&
      input.available_sample_count !== undefined
    ) {
      if (input.available_sample_count < input.minimum_sample_count) {
        throw new Error(
          `最小サンプル数 ${input.minimum_sample_count} が収集可能なサンプル数 ${input.available_sample_count} を超えています`
        );
      }
    }
  
    // Handle config-based input (SCEN-461)
    const config = input.config || {};
    const currentTime = input.currentTime || new Date();
  
    const collectionPeriodDays = config.collectionPeriodDays || 30;
    const minimumSampleCount = config.minimumSampleCount || 100;
    const userId = config.userId || "user-001";
    const familyMemberId = config.familyMemberId || "family-member-001";
  
    // Calculate collection start date (currentTime - collectionPeriodDays)
    const collectionStartDate = new Date(currentTime);
    collectionStartDate.setDate(
      collectionStartDate.getDate() - collectionPeriodDays
    );
  
    // Collection end date is the current time
    const collectionEndDate = new Date(currentTime);
  
    // Calculate next verification scheduled time based on cycle type
    let nextVerificationScheduledTime = new Date(currentTime);
    const cycleType = config.verificationCycleType || "monthly";
  
    if (cycleType === "monthly") {
      nextVerificationScheduledTime.setMonth(
        nextVerificationScheduledTime.getMonth() + 1
      );
    } else if (cycleType === "weekly") {
      nextVerificationScheduledTime.setDate(
        nextVerificationScheduledTime.getDate() + 7
      );
    }
  
    return {
      collectionPeriodDays,
      minimumSampleCount,
      collectionStartDate,
      collectionEndDate,
      collectionStatus: "started",
      userId,
      familyMemberId,
      instructionIssuedAt: currentTime,
      nextVerificationScheduledTime,
    };
  }
  return { instructDataCollection };
})();
