/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutrientAchievementScores exports=calculateNutrientAchievementScores */
const __aivicBundle_145_calculateNutrientAchievementScores = (() => {
  function calculateNutrientAchievementScores(
    userData: {
      age: number;
      gender: 'male' | 'female';
      activityLevel: 'sedentary' | 'light' | 'moderate' | 'active' | 'very_active';
    },
    intakeData: {
      userId: string;
      date: string;
      nutrients: Record<
        string,
        {
          intake: number;
          unit: string;
        }
      >;
    }
  ): Record<string, number> {
    if (!intakeData.userId || String(intakeData.userId).trim() === '') {
      throw new Error('userId is required');
    }
    if (!intakeData.date || String(intakeData.date).trim() === '') {
      throw new Error('date is required');
    }
  
    const nutritionStandards: Record<string, number> = {
      protein: 60,
      fat: 70,
      carbohydrate: 350,
      vitaminA: 800,
      vitaminC: 100,
      calcium: 800,
      iron: 8,
    };
  
    const result: Record<string, number> = {};
  
    for (const [nutrientName, standard] of Object.entries(nutritionStandards)) {
      const intakeInfo = intakeData.nutrients[nutrientName];
  
      if (!intakeInfo) {
        result[nutrientName] = 0;
        continue;
      }
  
      const { intake } = intakeInfo;
  
      if (standard === 0) {
        result[nutrientName] = 0;
        continue;
      }
  
      const achievementRate = (intake / standard) * 100;
      const cappedRate = Math.min(achievementRate, 100);
      const roundedRate = Math.round(cappedRate);
  
      result[nutrientName] = roundedRate;
    }
  
    userData.age;
    userData.gender;
    userData.activityLevel;
  
    return result;
  }
  return { calculateNutrientAchievementScores };
})();
