/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionGap exports=calculateNutritionGap */
const __aivicBundle_146_calculateNutritionGap = (() => {
  interface CalculateNutritionGapInput {
    nutritionItemId: string;
    nutritionItemName: string;
    targetValue: number;
    currentValue: number;
    unit: string;
    precision: number;
  }
  
  interface CalculateNutritionGapResult {
    gap: number;
    gapPercentage: number;
    isPositive: boolean;
  }
  
   function calculateNutritionGap(
    input: CalculateNutritionGapInput
  ): CalculateNutritionGapResult {
    const { targetValue, currentValue, precision } = input;
  
    if (targetValue < 0 || currentValue < 0) {
      throw new Error("栄養値は負の値を指定できません");
    }
  
    if (currentValue > targetValue) {
      throw new Error("目標値より現在値が高い場合は計算できません");
    }
  
    const gap = targetValue - currentValue;
    const gapPercentage =
      targetValue === 0 ? 0 : Math.round((gap / targetValue) * 100);
  
    const roundedGap = Math.round(gap * Math.pow(10, precision)) / Math.pow(10, precision);
  
    return {
      gap: roundedGap,
      gapPercentage,
      isPositive: gap > 0,
    };
  }
  return { calculateNutritionGap };
})();
export const calculateNutritionGap = __aivicBundle_146_calculateNutritionGap.calculateNutritionGap;
