/* AIVIC_FUNCTION_BUNDLE_START owner=evaluateNutritionLogic exports=evaluateNutritionLogic */
const __aivicBundle_148_evaluateNutritionLogic = (() => {
  function evaluateNutritionLogic(
    nutritionData: Array<{
      nutrient_id: number;
      nutrient_name: string;
      target_value: number;
      actual_value: number;
      achievement_rate: number;
    }>
  ): {
    items: Array<{
      nutrient_id: number;
      nutrient_name: string;
      achievement_rate: number;
      is_passed: boolean;
      judgement: string;
      priority_rank: number;
      improvement_gap?: number;
    }>;
    overall_judgement: string;
    failed_count: number;
    passed_count: number;
    failure_rate: number;
  } {
    if (!nutritionData || nutritionData.length === 0) {
      throw new Error("栄養データが提供されていません");
    }
  
    const evaluatedItems = nutritionData.map((item) => {
      if (item.achievement_rate < 0 || item.achievement_rate > 100) {
        throw new Error("達成度スコアが無効な範囲です");
      }
  
      const isPassed = item.achievement_rate >= 50;
      const improvementGap = Math.max(0, 100 - item.achievement_rate);
  
      return {
        nutrient_id: item.nutrient_id,
        nutrient_name: item.nutrient_name,
        achievement_rate: item.achievement_rate,
        is_passed: isPassed,
        judgement: isPassed ? "合格" : "不合格",
        improvement_gap: improvementGap,
        _sortKey: isPassed ? Infinity : improvementGap,
      };
    });
  
    const failedItems = evaluatedItems.filter((item) => !item.is_passed);
    failedItems.sort((a, b) => b._sortKey - a._sortKey);
  
    const itemsWithRank = evaluatedItems.map((item) => {
      let priorityRank = 0;
      if (!item.is_passed) {
        priorityRank = failedItems.findIndex((fi) => fi.nutrient_id === item.nutrient_id) + 1;
      } else {
        priorityRank = 0;
      }
  
      const result: any = {
        nutrient_id: item.nutrient_id,
        nutrient_name: item.nutrient_name,
        achievement_rate: item.achievement_rate,
        is_passed: item.is_passed,
        judgement: item.judgement,
        priority_rank: priorityRank,
      };
  
      if (item.improvement_gap > 0) {
        result.improvement_gap = item.improvement_gap;
      }
  
      return result;
    });
  
    const passedCount = evaluatedItems.filter((item) => item.is_passed).length;
    const failedCount = evaluatedItems.length - passedCount;
    const failureRate = evaluatedItems.length > 0 ? (failedCount / evaluatedItems.length) * 100 : 0;
    const overallJudgement = failedCount > 0 ? "不合格" : "合格";
  
    return {
      items: itemsWithRank,
      overall_judgement: overallJudgement,
      failed_count: failedCount,
      passed_count: passedCount,
      failure_rate: failureRate,
    };
  }
  return { evaluateNutritionLogic };
})();
