/* AIVIC_FUNCTION_BUNDLE_START owner=validateNutritionIntakeData exports=validateNutritionIntakeData */
const __aivicBundle_150_validateNutritionIntakeData = (() => {
  function validateNutritionIntakeData(
    nutritionData: NutrientIntakeData | NutrientIntakeData[] | { nutrientId: string; nutrientName: string; intakeAmount: number; unit: string; recordDate: string }
  ): { isValid: boolean; errorCount: number; errors: string[] } {
    const errors: string[] = [];
  
    // Handle both single object and array inputs
    const dataArray = Array.isArray(nutritionData) ? nutritionData : [nutritionData];
  
    for (const data of dataArray) {
      // Validate nutrientId exists
      if (!data.nutrientId || typeof data.nutrientId !== 'string') {
        errors.push('栄養素IDが不正です');
      }
  
      // Validate nutrientName exists
      if (!data.nutrientName || typeof data.nutrientName !== 'string') {
        errors.push('栄養素名が不正です');
      }
  
      // Validate intakeAmount is non-negative number
      if (typeof data.intakeAmount !== 'number') {
        errors.push(`${data.nutrientName || '栄養素'}の摂取量が数値ではありません`);
      } else if (data.intakeAmount < 0) {
        errors.push(`${data.nutrientName || '栄養素'}の摂取量が負数です`);
      }
  
      // Validate targetAmount if present
      if ('targetAmount' in data && data.targetAmount !== undefined) {
        if (typeof data.targetAmount !== 'number') {
          errors.push(`${data.nutrientName || '栄養素'}の目標量が数値ではありません`);
        } else if (data.targetAmount < 0) {
          errors.push(`${data.nutrientName || '栄養素'}の目標量が負数です`);
        }
      }
  
      // Validate unit exists
      if (!data.unit || typeof data.unit !== 'string') {
        errors.push('単位が不正です');
      }
  
      // Validate timestamp or recordDate exists
      const dateStr = ('timestamp' in data ? data.timestamp : undefined) || ('recordDate' in data ? (data as any).recordDate : undefined);
      if (!dateStr) {
        errors.push('記録日時が不正です');
      } else if (typeof dateStr === 'string') {
        const dateObj = new Date(dateStr);
        if (isNaN(dateObj.getTime())) {
          errors.push('記録日時の形式が不正です');
        }
      }
    }
  
    return {
      isValid: errors.length === 0,
      errorCount: errors.length,
      errors
    };
  }
  return { validateNutritionIntakeData };
})();
export const validateNutritionIntakeData: (...args: any[]) => any = (...args: any[]) => (__aivicBundle_150_validateNutritionIntakeData.validateNutritionIntakeData as (...args: any[]) => any)(...args);
