/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionPriorityOrder exports=calculateNutritionPriorityOrder */
const __aivicBundle_152_calculateNutritionPriorityOrder = (() => {
  function calculateNutritionPriorityOrder(
    nutritionItems: Array<{
      nutritionItemId: string;
      name: string;
      targetValue?: number;
      actualValue?: number;
      achievementRate: number;
      importanceScore: number;
      registrationOrder: number;
    }>
  ): Array<{
    nutritionItemId: string;
    name: string;
    achievementRate: number;
    importanceScore: number;
    registrationOrder: number;
    priorityRank: number;
  }> {
    if (nutritionItems.length === 0) {
      return [];
    }
  
    const itemsWithRank = nutritionItems.map((item) => ({
      nutritionItemId: item.nutritionItemId,
      name: item.name,
      achievementRate: item.achievementRate,
      importanceScore: item.importanceScore,
      registrationOrder: item.registrationOrder,
      sortKey: {
        achievementRate: item.achievementRate,
        importanceScore: item.importanceScore,
        registrationOrder: item.registrationOrder,
      },
    }));
  
    itemsWithRank.sort((a, b) => {
      if (a.sortKey.achievementRate !== b.sortKey.achievementRate) {
        return a.sortKey.achievementRate - b.sortKey.achievementRate;
      }
  
      if (a.sortKey.importanceScore !== b.sortKey.importanceScore) {
        return b.sortKey.importanceScore - a.sortKey.importanceScore;
      }
  
      return a.sortKey.registrationOrder - b.sortKey.registrationOrder;
    });
  
    return itemsWithRank.map((item, index) => ({
      nutritionItemId: item.nutritionItemId,
      name: item.name,
      achievementRate: item.achievementRate,
      importanceScore: item.importanceScore,
      registrationOrder: item.registrationOrder,
      priorityRank: index + 1,
    }));
  }
  return { calculateNutritionPriorityOrder };
})();
