const __aivicBundle_153_calculateNutritionPriority = (() => {
  function calculateNutritionPriority(
    nutritionData: Array<{
      item_id: string;
      target_value: number;
      actual_value: number;
    }> | null | undefined
  ): {
    priorities: Array<{
      item_id: string;
      achievement_rate: number;
      gap: number;
      priority_rank: number;
    }>;
    total_items: number;
    critical_items_count: number;
  } {
    if (!nutritionData || nutritionData.length === 0) {
      throw new Error("栄養項目データが提供されていません");
    }
  
    const priorities = nutritionData.map((item) => {
      const achievementRate = (item.actual_value / item.target_value) * 100;
      const gap = item.target_value - item.actual_value;
  
      return {
        item_id: item.item_id,
        achievement_rate: achievementRate,
        gap: gap,
        priority_rank: 0,
      };
    });
  
    priorities.sort((a, b) => {
      if (a.gap !== b.gap) {
        return b.gap - a.gap;
      }
      return a.achievement_rate - b.achievement_rate;
    });
  
    priorities.forEach((priority, index) => {
      priority.priority_rank = index + 1;
    });
  
    const criticalItemsCount = priorities.filter(
      (p) => p.achievement_rate < 50
    ).length;
  
    return {
      priorities,
      total_items: nutritionData.length,
      critical_items_count: criticalItemsCount,
    };
  }
  return { calculateNutritionPriority };
})();
