const __aivicBundle_160_calculateNutritionAchievementComparison = (() => {
  function calculateNutritionAchievementComparison(
    input: any,
    postImprovementData?: any,
    nutritionStandards?: any,
    selectedNutrients?: any
  ): any {
    // Detect input pattern: 1-arg vs 4-arg
    const isOneArgPattern = postImprovementData === undefined;
  
    if (isOneArgPattern) {
      // Pattern 1: Single object with before_achievement_rates and after_achievement_rates
      if (
        input &&
        typeof input === "object" &&
        !Array.isArray(input) &&
        "before_achievement_rates" in input &&
        "after_achievement_rates" in input
      ) {
        const before = input.before_achievement_rates;
        const after = input.after_achievement_rates;
  
        const correctedItems: string[] = [];
        const afterCorrected: Record<string, number> = {};
        const improvementGap: Record<string, number> = {};
  
        for (const key in after) {
          const correctedValue = after[key] > 100 ? 100 : after[key];
          afterCorrected[key] = correctedValue;
  
          if (after[key] > 100) {
            correctedItems.push(key);
          }
  
          improvementGap[key] = correctedValue - before[key];
        }
  
        const hasCorrection = correctedItems.length > 0;
        const warningMessage = hasCorrection
          ? `Correction applied: values exceeding 100% have been capped at 100%`
          : "";
  
        return {
          after_achievement_rates_corrected: afterCorrected,
          has_correction: hasCorrection,
          corrected_items: correctedItems,
          before_achievement_rates: before,
          improvement_gap: improvementGap,
          warning_message: warningMessage,
          correction_applied_indicator: hasCorrection,
        };
      }
    } else {
      // Pattern 2: Four arguments (arrays and objects)
      const preData = input as Array<Record<string, any>>;
      const postData = postImprovementData as Array<Record<string, any>>;
      const standards = nutritionStandards as Record<string, number>;
      const nutrients = selectedNutrients as string[];
  
      // Calculate averages for pre and post periods
      const preAverages: Record<string, number> = {};
      const postAverages: Record<string, number> = {};
  
      for (const nutrient of nutrients) {
        const preSum = preData.reduce((sum, record) => sum + (record[nutrient] || 0), 0);
        const postSum = postData.reduce((sum, record) => sum + (record[nutrient] || 0), 0);
  
        preAverages[nutrient] = preSum / preData.length;
        postAverages[nutrient] = postSum / postData.length;
      }
  
      // Calculate achievement percentages
      const preImprovement: Record<string, any> = {};
      const postImprovement: Record<string, any> = {};
      const effectDifference: Record<string, any> = {};
      const comparisonData: Array<any> = [];
  
      for (const nutrient of nutrients) {
        const preAchievementPercentage = Number(
          ((preAverages[nutrient] / standards[nutrient]) * 100).toFixed(1)
        );
        const postAchievementPercentage = Number(
          ((postAverages[nutrient] / standards[nutrient]) * 100).toFixed(1)
        );
  
        preImprovement[nutrient] = {
          achievementPercentage: preAchievementPercentage,
          actualValue: preAverages[nutrient],
          targetValue: standards[nutrient],
        };
  
        postImprovement[nutrient] = {
          achievementPercentage: postAchievementPercentage,
          actualValue: postAverages[nutrient],
          targetValue: standards[nutrient],
        };
  
        const absoluteDifference = Number(
          (postAchievementPercentage - preAchievementPercentage).toFixed(1)
        );
        const percentageDifference = Number(
          (
            ((postAchievementPercentage - preAchievementPercentage) /
              preAchievementPercentage) *
            100
          ).toFixed(1)
        );
  
        effectDifference[nutrient] = {
          absoluteDifference,
          percentageDifference,
        };
  
        comparisonData.push({
          nutrient,
          preAchievementPercentage,
          postAchievementPercentage,
          effectDifference: absoluteDifference,
          effectPercentageChange: percentageDifference,
        });
      }
  
      // Generate graph data
      const graphData = {
        labels: nutrients,
        preImprovementDataset: nutrients.map(
          (n) => preImprovement[n].achievementPercentage
        ),
        postImprovementDataset: nutrients.map(
          (n) => postImprovement[n].achievementPercentage
        ),
      };
  
      // Generate table data
      const tableData = comparisonData;
  
      return {
        preImprovement,
        postImprovement,
        effectDifference,
        comparisonData,
        graphData,
        tableData,
      };
    }
  
    return {};
  }
  return { calculateNutritionAchievementComparison };
})();
