    const satisfactionScore = input.userSatisfactionScore ?? 4.5;
    const timeSeries = input.timeSeriesData ?? [];
  
    // Calculate accuracy gap
    const accuracyGap = targetAccuracy - currentAccuracy;
  
    // Analyze trend from time series
    let trend = 'stable';
    if (timeSeries.length >= 2) {
      const firstAccuracy = timeSeries[0].accuracyRate;
      const lastAccuracy = timeSeries[timeSeries.length - 1].accuracyRate;
      if (lastAccuracy > firstAccuracy) {
        trend = 'improving';
      } else if (lastAccuracy < firstAccuracy) {
        trend = 'declining';
      }
    }
  
    // Calculate necessity score (0-100)
    let necessityScore = 0;
  
    // Accuracy gap contribution (0-40 points)
    necessityScore += Math.min(accuracyGap * 100, 40);
  
    // Failure pattern contribution (0-30 points)
    const failureScore = Math.min((failureCount / 20) * 30, 30);
    necessityScore += failureScore;
  
    // User satisfaction contribution (0-30 points)
    const satisfactionGap = 5 - satisfactionScore;
    const satisfactionScore_contrib = Math.max(0, Math.min((satisfactionGap / 5) * 30, 30));
    necessityScore += satisfactionScore_contrib;
  
    // Trend adjustment
    if (trend === 'declining') {
      necessityScore = Math.min(necessityScore + 10, 100);
    } else if (trend === 'improving') {
      necessityScore = Math.max(necessityScore - 5, 0);
    }
  
