    const weeklyDemandThresholdMax = input.weekly_demand_threshold_max ?? 1.4;
  
    // Validate seasonal variance
    const seasonalVarianceStatus =
      seasonalDemandVariance >= seasonalVarianceThresholdMin &&
      seasonalDemandVariance <= seasonalVarianceThresholdMax
        ? "within_normal_range"
        : "outside_normal_range";
  
    // Validate weekly pattern (all daily indices within thresholds)
    const dailyIndices = [
      input.monday_demand_index ?? 1.0,
      input.tuesday_demand_index ?? 1.0,
      input.wednesday_demand_index ?? 1.0,
      input.thursday_demand_index ?? 1.0,
      input.friday_demand_index ?? 1.0,
      input.saturday_demand_index ?? 1.0,
      input.sunday_demand_index ?? 1.0,
    ];
  
    const weeklyPatternStatus = dailyIndices.every(
      (idx) => idx >= weeklyDemandThresholdMin && idx <= weeklyDemandThresholdMax
    )
      ? "within_normal_range"
      : "outside_normal_range";
  
    // Validate confidence
    const confidenceStatus =
      confidenceScore >= confidenceThreshold ? "acceptable" : "unacceptable";
  
    // Validate sample adequacy
    const sampleAdequacyStatus =
      sampleCount >= minimumSampleCount ? "adequate" : "inadequate";
  
    // Validate anomaly
    const anomalyStatus = anomalyDetected ? "anomaly_detected" : "no_anomaly";
  
    // Calculate overall validation score
    const scoreComponents = [
      seasonalVarianceStatus === "within_normal_range" ? 1.0 : 0.5,
      weeklyPatternStatus === "within_normal_range" ? 1.0 : 0.5,
      confidenceStatus === "acceptable" ? 1.0 : 0.5,
      sampleAdequacyStatus === "adequate" ? 1.0 : 0.5,
      anomalyStatus === "no_anomaly" ? 1.0 : 0.3,
    ];
    const overallValidationScore =
      scoreComponents.reduce((a, b) => a + b, 0) / scoreComponents.length;
  
