/* AIVIC_FUNCTION_BUNDLE_START owner=filterAbnormalAndMissingValues exports=filterAbnormalAndMissingValues */
const __aivicBundle_172_filterAbnormalAndMissingValues = (() => {
  function filterAbnormalAndMissingValues(
    input: any
  ): {
    validData: any[];
    isolatedData: any[];
    filteringLog: Array<{
      recordId: string;
      filterReason: string;
      detectionMethod: string;
      timestamp: string;
    }>;
    filteringSummary: {
      totalInputRecords: number;
      validRecords: number;
      isolatedRecords: number;
      abnormalValueCount: number;
      missingValueCount: number;
      validDataPassThroughRate: number;
    };
    dataForAnalysisEngine: any[];
    isolatedDataExcludedFromAnalysis: boolean;
  } {
    const records = Array.isArray(input) ? input : input.records || [];
    const lowerBound = input.lowerBound ?? 0;
    const upperBound = input.upperBound ?? 10000;
  
    const validData: any[] = [];
    const isolatedData: any[] = [];
    const filteringLog: Array<{
      recordId: string;
      filterReason: string;
      detectionMethod: string;
      timestamp: string;
    }> = [];
  
    let abnormalValueCount = 0;
    let missingValueCount = 0;
  
    const timestamp = new Date().toISOString();
  
    for (const record of records) {
      const intakeAmount = record.intakeAmount;
      const recordId =
        record.recordId ||
        `${record.sourceId || 'UNKNOWN'}_${record.userId || 'UNKNOWN'}_${record.nutrientId || 'UNKNOWN'}`;
  
      // Check for missing values (null or undefined)
      if (intakeAmount === null || intakeAmount === undefined) {
        isolatedData.push({
          ...record,
          isolationReason: 'MISSING_VALUE',
        });
        missingValueCount++;
        const detectionMethod =
          intakeAmount === null ? 'NULL_CHECK' : 'UNDEFINED_CHECK';
        filteringLog.push({
          recordId,
          filterReason: 'MISSING_VALUE',
          detectionMethod,
          timestamp,
        });
        continue;
      }
  
      // Check for abnormal values (outside bounds or negative)
      if (intakeAmount < lowerBound || intakeAmount > upperBound) {
        isolatedData.push({
          ...record,
          isolationReason: 'ABNORMAL_VALUE',
        });
        abnormalValueCount++;
        filteringLog.push({
          recordId,
          filterReason: 'ABNORMAL_VALUE',
          detectionMethod: 'RANGE_CHECK',
          timestamp,
        });
        continue;
      }
  
      // Valid record
      validData.push(record);
    }
  
    const totalInputRecords = records.length;
    const validRecords = validData.length;
    const isolatedRecords = isolatedData.length;
    const validDataPassThroughRate =
      totalInputRecords > 0 ? (validRecords / totalInputRecords) * 100 : 0;
  
    return {
      validData,
      isolatedData,
      filteringLog,
      filteringSummary: {
        totalInputRecords,
        validRecords,
        isolatedRecords,
        abnormalValueCount,
        missingValueCount,
        validDataPassThroughRate,
      },
      dataForAnalysisEngine: validData,
      isolatedDataExcludedFromAnalysis: isolatedRecords > 0,
    };
  }
  return { filterAbnormalAndMissingValues };
})();
