/* AIVIC_FUNCTION_BUNDLE_START owner=calculateNutritionBalanceValidation exports=calculateNutritionBalanceValidation */
const __aivicBundle_175_calculateNutritionBalanceValidation = (() => {
  function calculateNutritionBalanceValidation(input: {
    userId: string;
    nutritionRecords: Array<{
      date: string;
      protein?: number;
      carbohydrate?: number;
      fat?: number;
      fiber?: number;
    }>;
    targetNutrition: {
      protein?: { min: number; max: number };
      carbohydrate?: { min: number; max: number };
      fat?: { min: number; max: number };
      fiber?: { min: number; max: number };
    };
    dietaryRestrictions?: string[];
  }): {
    validationStatus: string;
    achievementScores: Record<string, number>;
    deficiencyItems: Array<{
      nutrientName: string;
      gap: number;
      gapPercentage: number;
      priority: 'high' | 'medium' | 'low';
    }>;
    processedAt: string;
  } {
    if (!input.userId || String(input.userId).trim() === '') {
      throw new Error('userId is required');
    }
  
    if (!input.nutritionRecords || input.nutritionRecords.length === 0) {
      throw new Error('栄養記録が必要です');
    }
  
    const nutrients = ['protein', 'carbohydrate', 'fat', 'fiber'] as const;
    const achievementScores: Record<string, number> = {};
    const deficiencyItems: Array<{
      nutrientName: string;
      gap: number;
      gapPercentage: number;
      priority: 'high' | 'medium' | 'low';
    }> = [];
  
    for (const nutrient of nutrients) {
      const target = input.targetNutrition[nutrient];
      if (!target) continue;
  
      const values = input.nutritionRecords
        .map((record) => record[nutrient] ?? 0)
        .filter((v) => v > 0);
  
      if (values.length === 0) {
        achievementScores[nutrient] = 0;
        const gap = target.min;
        const gapPercentage = 100;
        deficiencyItems.push({
          nutrientName: nutrient,
          gap,
          gapPercentage,
          priority: 'high',
        });
        continue;
      }
  
      const actualAverage = values.reduce((a, b) => a + b, 0) / values.length;
  
      let score = 100;
      if (actualAverage < target.min) {
        const deviation = target.min - actualAverage;
        score = Math.max(0, 100 - (deviation / target.min) * 100);
      } else if (actualAverage > target.max) {
        const deviation = actualAverage - target.max;
        score = Math.max(0, 100 - (deviation / target.max) * 100);
      }
  
      achievementScores[nutrient] = Math.round(score);
  
      if (actualAverage < target.min) {
        const gap = target.min - actualAverage;
        const gapPercentage = (gap / target.min) * 100;
        let priority: 'low' | 'medium' | 'high' = 'low';
        if (gapPercentage > 30) priority = 'high';
        else if (gapPercentage > 15) priority = 'medium';
  
        deficiencyItems.push({
          nutrientName: nutrient,
          gap: Math.round(gap * 10) / 10,
          gapPercentage: Math.round(gapPercentage * 10) / 10,
          priority,
        });
      }
    }
  
    const validationStatus =
      deficiencyItems.length === 0 ? 'balanced' : 'imbalanced';
  
    return {
      validationStatus,
      achievementScores,
      deficiencyItems,
      processedAt: new Date().toISOString(),
    };
  }
  return { calculateNutritionBalanceValidation };
})();
export const calculateNutritionBalanceValidation = __aivicBundle_175_calculateNutritionBalanceValidation.calculateNutritionBalanceValidation;
/* AIVIC_FUNCTION_BUNDLE_END owner=calculateNutritionBalanceValidation */

/* AIVIC_FUNCTION_BUNDLE_START owner=detectSLAExceeded exports=detectSLAExceeded */
const __aivicBundle_176_detectSLAExceeded = (() => {
  function detectSLAExceeded(input: {
    requestTimestamp: string;
    currentTimestamp: string;
    slaThresholdMs?: number;
  }): {
    isExceeded: boolean;
    elapsedMs: number;
    excessMs: number;
    detectedAt: string;
  } {
    // Validate timestamps
    const requestTime = new Date(input.requestTimestamp);
    const currentTime = new Date(input.currentTimestamp);
  
    if (isNaN(requestTime.getTime())) {
      throw new Error('リクエストタイムスタンプが無効です');
    }
    if (isNaN(currentTime.getTime())) {
      throw new Error('現在のタイムスタンプが無効です');
    }
  
    // Validate SLA threshold
    const slaThresholdMs = input.slaThresholdMs ?? 0;
    if (slaThresholdMs < 0) {
      throw new Error('SLA閾値は0以上である必要があります');
    }
  
    // Calculate elapsed time in milliseconds
    const elapsedMs = currentTime.getTime() - requestTime.getTime();
  
    // Determine if SLA is exceeded
    const isExceeded = elapsedMs > slaThresholdMs;
  
    // Calculate excess time (0 if within SLA)
    const excessMs = isExceeded ? elapsedMs - slaThresholdMs : 0;
  
    return {
      isExceeded,
      elapsedMs,
      excessMs,
      detectedAt: input.currentTimestamp,
    };
  }
  return { detectSLAExceeded };
})();
export const detectSLAExceeded = __aivicBundle_176_detectSLAExceeded.detectSLAExceeded;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectSLAExceeded */

