/* AIVIC_FUNCTION_BUNDLE_START owner=calculateCookingTimeImprovement exports=calculateCookingTimeImprovement */
const __aivicBundle_188_calculateCookingTimeImprovement = (() => {
  function calculateCookingTimeImprovement(input: {
    beforeCookingTime: number;
    afterCookingTime: number;
    targetImprovementRate: number;
  }): {
    improvementRate: number;
    improvementMinutes: number;
    meetsTarget: boolean;
  } {
    const { beforeCookingTime, afterCookingTime, targetImprovementRate } = input;
  
    if (beforeCookingTime <= 0) {
      throw new Error('調理時間は正の値である必要があります');
    }
  
    if (afterCookingTime < 0) {
      throw new Error('調理時間は非負の値である必要があります');
    }
  
    const improvementMinutes = beforeCookingTime - afterCookingTime;
  
    if (improvementMinutes < 0) {
      throw new Error('調理時間短縮度が負の値です。調理時間が増加しています');
    }
  
    const improvementRate = improvementMinutes / beforeCookingTime;
    const meetsTarget = improvementRate >= targetImprovementRate;
  
    return {
      improvementRate,
      improvementMinutes,
      meetsTarget,
    };
  }
  return { calculateCookingTimeImprovement };
})();
