/* AIVIC_FUNCTION_BUNDLE_START owner=calculateAlgorithmImprovementMetrics exports=calculateAlgorithmImprovementMetrics */
const __aivicBundle_189_calculateAlgorithmImprovementMetrics = (() => {
  interface CalculateAlgorithmImprovementMetricsInput {
    userSatisfactionScore?: number;
    mealGenerationSuccessRateImprovement?: number;
    cookingTimeReductionDegree?: number;
    weeklyComparison?: number;
    preImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      userSatisfactionScore: number;
      timestamp: Date;
    } | null;
    postImprovementMetrics?: {
      successRate: number;
      cookingTimeReduction: number;
      userSatisfactionScore: number;
      timestamp: Date;
    } | null;
  }
  
  interface CalculateAlgorithmImprovementMetricsOutput {
    improvementEffectScore?: number;
    successRateImprovement?: number;
    cookingTimeReductionImprovement?: number;
    userSatisfactionScoreImprovement?: number;
    overallImprovementScore?: number;
    errorOccurred: boolean;
    errorMessage: string | null;
  }
  
   function calculateAlgorithmImprovementMetrics(
    input: CalculateAlgorithmImprovementMetricsInput
  ): CalculateAlgorithmImprovementMetricsOutput {
    // Handle pre/post improvement metrics mode (from test itg-2-scen-576)
    if (
      input.preImprovementMetrics !== undefined ||
      input.postImprovementMetrics !== undefined
    ) {
      if (!input.preImprovementMetrics && !input.postImprovementMetrics) {
        return {
          errorOccurred: true,
          errorMessage: "改善前後データが不足しています",
        };
      }
  
      if (!input.preImprovementMetrics) {
        return {
          errorOccurred: true,
          errorMessage: "改善前データが不足しています",
        };
      }
  
      if (!input.postImprovementMetrics) {
        return {
          errorOccurred: true,
          errorMessage: "改善後データが不足しています",
        };
      }
  
      const pre = input.preImprovementMetrics;
      const post = input.postImprovementMetrics;
  
      // Calculate percentage improvements
      const successRateImprovement =
        ((post.successRate - pre.successRate) / pre.successRate) * 100;
      const cookingTimeReductionImprovement =
        ((post.cookingTimeReduction - pre.cookingTimeReduction) /
          pre.cookingTimeReduction) *
        100;
      const userSatisfactionScoreImprovement =
        ((post.userSatisfactionScore - pre.userSatisfactionScore) /
          pre.userSatisfactionScore) *
        100;
  
      // Calculate overall improvement score as average of three metrics
      const overallImprovementScore =
        (successRateImprovement +
          cookingTimeReductionImprovement +
          userSatisfactionScoreImprovement) /
        3;
  
      return {
        successRateImprovement: Math.round(successRateImprovement * 100) / 100,
        cookingTimeReductionImprovement:
          Math.round(cookingTimeReductionImprovement * 100) / 100,
        userSatisfactionScoreImprovement:
          Math.round(userSatisfactionScoreImprovement * 100) / 100,
        overallImprovementScore:
          Math.round(overallImprovementScore * 100) / 100,
        errorOccurred: false,
        errorMessage: null,
      };
    }
  
    // Handle satisfaction score boundary mode (from test itg-2-scen-575)
    const userSatisfactionScore = input.userSatisfactionScore ?? 0;
    const mealGenerationSuccessRateImprovement =
      input.mealGenerationSuccessRateImprovement ?? 0;
    const cookingTimeReductionDegree =
      input.cookingTimeReductionDegree ?? 0;
    const weeklyComparison = input.weeklyComparison ?? 1;
  
    // Formula: (successRate * 0.4 + cookingTime * 0.35 + (weeklyComparison - 1) * 10 * 0.25) * (userSatisfactionScore / 100)
    const baseScore =
      mealGenerationSuccessRateImprovement * 0.4 +
      cookingTimeReductionDegree * 0.35 +
      (weeklyComparison - 1) * 10 * 0.25;
  
    const improvementEffectScore =
      baseScore * (userSatisfactionScore / 100);
  
    // Clamp to [0, 100]
    const clampedScore = Math.max(0, Math.min(100, improvementEffectScore));
  
    return {
      improvementEffectScore: Math.round(clampedScore * 100) / 100,
      errorOccurred: false,
      errorMessage: null,
    };
  }
  return { calculateAlgorithmImprovementMetrics };
})();
export const calculateAlgorithmImprovementMetrics = __aivicBundle_189_calculateAlgorithmImprovementMetrics.calculateAlgorithmImprovementMetrics;
