/* AIVIC_FUNCTION_BUNDLE_START owner=classifyMenuFailurePatterns exports=classifyMenuFailurePatterns */
const __aivicBundle_192_classifyMenuFailurePatterns = (() => {
  function classifyMenuFailurePatterns(input: {
    failures: Array<{
      failure_id: number;
      user_id: string;
      menu_id: string;
      rejection_reason: string;
      rejection_category: string;
      failure_date: string;
      impact_score: number;
      correction_effectiveness: number;
    }>;
    analysis_period_start: string;
    analysis_period_end: string;
  }): {
    classified_patterns: Array<{
      category: string;
      occurrence_count: number;
      impact_score: number;
      correction_effectiveness: number;
      severity: 'low' | 'medium' | 'high';
    }>;
  } {
    const { failures, analysis_period_start, analysis_period_end } = input;
  
    const categoryMap = new Map<
      string,
      {
        category: string;
        occurrences: number;
        totalImpactScore: number;
        totalCorrectionEffectiveness: number;
      }
    >();
  
    const periodStart = new Date(analysis_period_start);
    const periodEnd = new Date(analysis_period_end);
  
    for (const failure of failures) {
      const failureDate = new Date(failure.failure_date);
  
      if (failureDate < periodStart || failureDate > periodEnd) {
        continue;
      }
  
      const category = failure.rejection_category;
  
      if (!categoryMap.has(category)) {
        categoryMap.set(category, {
          category,
          occurrences: 0,
          totalImpactScore: 0,
          totalCorrectionEffectiveness: 0,
        });
      }
  
      const entry = categoryMap.get(category)!;
      entry.occurrences += 1;
      entry.totalImpactScore += failure.impact_score;
      entry.totalCorrectionEffectiveness += failure.correction_effectiveness;
    }
  
    const classifiedPatterns = Array.from(categoryMap.values())
      .filter((entry) => entry.occurrences > 0)
      .map((entry) => {
        const avgImpactScore = entry.totalImpactScore / entry.occurrences;
        const avgCorrectionEffectiveness =
          entry.totalCorrectionEffectiveness / entry.occurrences;
  
        let severity: 'low' | 'medium' | 'high';
        if (avgImpactScore >= 7) {
          severity = 'high';
        } else if (avgImpactScore >= 5) {
          severity = 'medium';
        } else {
          severity = 'low';
        }
  
        return {
          category: entry.category,
          occurrence_count: entry.occurrences,
          impact_score: Math.round(avgImpactScore * 100) / 100,
          correction_effectiveness:
            Math.round(avgCorrectionEffectiveness * 100) / 100,
          severity,
        };
      })
      .sort((a, b) => b.occurrence_count - a.occurrence_count);
  
    return {
      classified_patterns: classifiedPatterns,
    };
  }
  return { classifyMenuFailurePatterns };
})();
export const classifyMenuFailurePatterns = __aivicBundle_192_classifyMenuFailurePatterns.classifyMenuFailurePatterns;
/* AIVIC_FUNCTION_BUNDLE_END owner=classifyMenuFailurePatterns */

/* AIVIC_FUNCTION_BUNDLE_START owner=rankImprovementPriority exports=rankImprovementPriority */
const __aivicBundle_193_rankImprovementPriority = (() => {
  function rankImprovementPriority(input: {
    classified_patterns: Array<{
      category: string;
      occurrence_count: number;
      impact_score: number;
      correction_effectiveness: number;
    }>;
    weighting_config: {
      occurrence_weight: number;
      impact_weight: number;
      effectiveness_weight: number;
    };
  }): {
    ranked_priorities: Array<{
      rank: number;
      category: string;
      priority_rank: "HIGH" | "MEDIUM" | "LOW";
      priority_score: number;
    }>;
  } {
    const { classified_patterns, weighting_config } = input;
  
    if (!classified_patterns || classified_patterns.length === 0) {
      return { ranked_priorities: [] };
    }
  
    const scoredPatterns = classified_patterns.map((pattern) => {
      const normalizedOccurrence =
        Math.min(pattern.occurrence_count / 10, 1) *
        weighting_config.occurrence_weight;
      const normalizedImpact =
        Math.min(pattern.impact_score / 10, 1) * weighting_config.impact_weight;
      const normalizedEffectiveness =
        pattern.correction_effectiveness *
        weighting_config.effectiveness_weight;
  
      const priorityScore =
        (normalizedOccurrence + normalizedImpact + normalizedEffectiveness) * 100;
  
      let priority_rank: "HIGH" | "MEDIUM" | "LOW";
      if (priorityScore >= 70) {
        priority_rank = "HIGH";
      } else if (priorityScore >= 50) {
        priority_rank = "MEDIUM";
      } else {
        priority_rank = "LOW";
      }
  
      return {
        category: pattern.category,
        priority_score: Math.round(priorityScore),
        priority_rank,
        occurrence_count: pattern.occurrence_count,
      };
    });
  
    scoredPatterns.sort((a, b) => b.priority_score - a.priority_score);
  
    const ranked_priorities = scoredPatterns.map((pattern, index) => ({
      rank: index + 1,
      category: pattern.category,
      priority_rank: pattern.priority_rank,
      priority_score: pattern.priority_score,
    }));
  
    return { ranked_priorities };
  }
  return { rankImprovementPriority };
})();
export const rankImprovementPriority = __aivicBundle_193_rankImprovementPriority.rankImprovementPriority;
/* AIVIC_FUNCTION_BUNDLE_END owner=rankImprovementPriority */

/* AIVIC_FUNCTION_BUNDLE_START owner=confirmMeetingAttendance exports=confirmMeetingAttendance */
const __aivicBundle_194_confirmMeetingAttendance = (() => {
  function confirmMeetingAttendance(input: any): any {
    const {
      meeting_id,
      meeting_date,
      meeting_type,
      meeting_title,
      scheduled_attendees,
      confirmed_attendees,
      confirmation_timestamp,
      attendees,
    } = input;
  
    // Pattern 1: scheduled_attendees + confirmed_attendees (first test scenario)
    if (scheduled_attendees && confirmed_attendees) {
      const total_scheduled_count = scheduled_attendees.length;
      const confirmed_count = confirmed_attendees.filter(
        (c: any) => c.attendance_status === 'confirmed'
      ).length;
      const absent_count = confirmed_attendees.filter(
        (c: any) => c.attendance_status === 'absent'
      ).length;
      const pending_count = total_scheduled_count - confirmed_count - absent_count;
  
      const confirmation_status =
        pending_count === 0 ? 'all_confirmed' : 'partial_confirmed';
  
      const updated_scheduled_attendees = scheduled_attendees.map(
        (scheduled: any) => {
          const confirmed = confirmed_attendees.find(
            (c: any) => c.attendee_id === scheduled.attendee_id
          );
          return {
            ...scheduled,
            attendance_status: confirmed?.attendance_status || 'pending',
            confirmation_timestamp:
              confirmed?.confirmation_timestamp || scheduled.confirmation_timestamp,
          };
        }
      );
  
      return {
        meeting_id,
        meeting_date,
        meeting_type,
        total_scheduled_count,
        confirmed_count,
        absent_count,
        pending_count,
        confirmation_status,
        confirmation_timestamp,
        scheduled_attendees: updated_scheduled_attendees,
        message:
          confirmation_status === 'all_confirmed'
            ? '全参加予定者の出席確認が完了しました'
            : '一部参加予定者の出席確認が未完了です',
        database_save_status: 'success',
      };
    }
  
    // Pattern 2: attendees array with delegate info (second test scenario)
    if (attendees && Array.isArray(attendees)) {
      const total_attendees = attendees.length;
      const present_count = attendees.filter(
        (a: any) => a.status === 'present'
      ).length;
      const absent_count = attendees.filter(
        (a: any) => a.status === 'absent'
      ).length;
  
      const delegates_assigned_count = attendees.filter(
        (a: any) => a.status === 'absent' && a.delegate_user_id
      ).length;
  
      const all_absent_have_delegates =
        absent_count > 0
          ? delegates_assigned_count === absent_count
          : true;
  
      const meeting_status =
        all_absent_have_delegates && (present_count > 0 || delegates_assigned_count > 0)
          ? 'confirmed'
          : 'pending';
  
      const confirmed_at = new Date().toISOString();
  
      const attendee_list = attendees.map((a: any) => ({
        attendee_id: a.attendee_id,
        user_id: a.user_id,
        name: a.name,
        status: a.status,
        delegate_user_id: a.delegate_user_id,
        delegate_name: a.delegate_name || null,
      }));
  
      return {
        meeting_id,
        meeting_date,
        meeting_title,
        total_attendees,
        present_count,
        absent_count,
        delegates_assigned_count,
        all_absent_have_delegates,
        meeting_status,
        confirmed_at,
        attendee_list,
      };
    }
  
    return {};
  }
  return { confirmMeetingAttendance };
})();
export const confirmMeetingAttendance = __aivicBundle_194_confirmMeetingAttendance.confirmMeetingAttendance;
/* AIVIC_FUNCTION_BUNDLE_END owner=confirmMeetingAttendance */

