/* AIVIC_FUNCTION_BUNDLE_START owner=determineNextPriorityAfterImprovement exports=determineNextPriorityAfterImprovement */
const __aivicBundle_199_determineNextPriorityAfterImprovement = (() => {
  function determineNextPriorityAfterImprovement(input: {
    judgment_status: string;
    current_priority: number;
    improvement_delta: number;
  }): {
    next_priority: number;
    priority_adjusted: boolean;
    reason: string;
  } {
    const { judgment_status, current_priority, improvement_delta } = input;
  
    if (judgment_status === 'No Improvement' || improvement_delta === 0) {
      return {
        next_priority: current_priority,
        priority_adjusted: false,
        reason: `No Improvement detected. Current priority level remains at ${current_priority}.`,
      };
    }
  
    if (improvement_delta > 0) {
      const adjustedPriority = Math.max(1, current_priority - 1);
      return {
        next_priority: adjustedPriority,
        priority_adjusted: true,
        reason: `Improvement detected with delta ${improvement_delta}. Priority upgraded from ${current_priority} to ${adjustedPriority}.`,
      };
    }
  
    const adjustedPriority = Math.min(5, current_priority + 1);
    return {
      next_priority: adjustedPriority,
      priority_adjusted: true,
      reason: `Negative improvement detected with delta ${improvement_delta}. Priority downgraded from ${current_priority} to ${adjustedPriority}.`,
    };
  }
  return { determineNextPriorityAfterImprovement };
})();
