/* AIVIC_FUNCTION_BUNDLE_START owner=classifyMenuRejectReason exports=classifyMenuRejectReason */
const __aivicBundle_203_classifyMenuRejectReason = (() => {
  interface ClassifyMenuRejectReasonInput {
    rejectReason: string;
  }
  
  interface ClassifyMenuRejectReasonResult {
    category?: string;
    confidence?: number;
    isSuccessfullyClassified: boolean;
    error?: string;
    timestamp: string;
    logLevel: 'info' | 'warn' | 'error';
  }
  
  const predefinedCategories = [
    '味付け不適切',
    '栄養バランス不足',
    '調理時間超過',
    'その他',
    '未分類',
  ];
  
  const categoryKeywords: Record<string, string[]> = {
    '味付け不適切': ['塩辛', '甘い', '味付け', '味が', '辛い', '薄い', '濃い'],
    '栄養バランス不足': ['栄養', 'バランス', '野菜', 'タンパク質', '栄養価'],
    '調理時間超過': ['時間', 'かかりすぎ', '長い', '遅い', '調理'],
  };
  
  function calculateConfidence(
    reason: string,
    category: string
  ): number {
    if (!reason || reason.trim().length === 0) {
      return 0;
    }
  
    const keywords = categoryKeywords[category] || [];
    if (keywords.length === 0) {
      return 0.3;
    }
  
    const matchedKeywords = keywords.filter((keyword) =>
      reason.toLowerCase().includes(keyword.toLowerCase())
    );
  
    const baseConfidence = matchedKeywords.length / keywords.length;
    const reasonLength = reason.trim().length;
    const lengthBonus = Math.min(reasonLength / 50, 0.2);
  
    return Math.min(baseConfidence + lengthBonus, 1);
  }
  
  function classifyReason(reason: string): string | null {
    if (!reason || reason.trim().length === 0) {
      return null;
    }
  
    const trimmedReason = reason.trim();
    const hasOnlySpecialChars = /^[!@#$%^&*()\-_=+\[\]{};:'",.<>?/\\|`~]+$/.test(
      trimmedReason
    );
  
    if (hasOnlySpecialChars) {
      return null;
    }
  
    let bestCategory: string | null = null;
    let bestScore = 0;
  
    for (const category of Object.keys(categoryKeywords)) {
      const keywords = categoryKeywords[category];
      const matchCount = keywords.filter((keyword) =>
        trimmedReason.toLowerCase().includes(keyword.toLowerCase())
      ).length;
  
      if (matchCount > bestScore) {
        bestScore = matchCount;
        bestCategory = category;
      }
    }
  
    if (bestCategory && bestScore > 0) {
      return bestCategory;
    }
  
    return null;
  }
  
   function classifyMenuRejectReason(
    input: ClassifyMenuRejectReasonInput
  ): ClassifyMenuRejectReasonResult {
    const { rejectReason } = input;
    const timestamp = new Date().toISOString();
  
    if (!rejectReason || rejectReason.trim().length === 0) {
      return {
        isSuccessfullyClassified: false,
        error: '空の入力です。却下理由を入力してください。',
        timestamp,
        logLevel: 'error',
      };
    }
  
    const classifiedCategory = classifyReason(rejectReason);
  
    if (classifiedCategory) {
      const confidence = calculateConfidence(rejectReason, classifiedCategory);
      return {
        category: classifiedCategory,
        confidence,
        isSuccessfullyClassified: true,
        timestamp,
        logLevel: 'info',
      };
    }
  
    const defaultCategory = 'その他';
    const defaultConfidence = calculateConfidence(rejectReason, defaultCategory);
  
    return {
      category: defaultCategory,
      confidence: defaultConfidence,
      isSuccessfullyClassified: true,
      timestamp,
      logLevel: 'warn',
    };
  }
  return { classifyMenuRejectReason };
})();
export const classifyMenuRejectReason = __aivicBundle_203_classifyMenuRejectReason.classifyMenuRejectReason;
